//! Golden-corpus runner — the native half of tempura's determinism gate.
//!
//! Each `corpus/<case>/` directory holds:
//!
//!   - a pinned input: `doc.sjon` (a timeline document, hand-authored),
//!     or `song.mid` / `song.it` (GENERATED by `zig build fixtures` from
//!     `tools/gen_fixtures.zig` and COMMITTED, so the bytes a golden
//!     describes are in the tree beside it);
//!   - `times.sjon` — the harness: an ordered script of directives,
//!     validated against `schema/tempura-corpus.sjon`;
//!   - `expected.sjon` — the GENERATED golden, one canonical text.
//!
//! `zig build corpus -- --update` regenerates the goldens; the diff is
//! reviewed, and a golden is never hand-edited. This runner is the
//! AUTHORITY for that text: at E3 the wasm half re-derives the same
//! bytes and compares against these same goldens, and that second
//! comparison is where native-vs-wasm equality gets asserted (pacer's
//! rule verbatim). Until it lands, this is the only side reading them.
//!
//! ## The harness
//!
//! Hand-authored, VALIDATED against the corpus manifest — a second
//! preloaded bundle, `Schema.loadCorpus`, never composed with the
//! timeline one. Directives run in DOCUMENT ORDER:
//!
//!     (read)                  ; what the core made of the bytes
//!     (roundtrip)             ; rungs 1 and 2 of plan 09's ladder
//!     (walk :max-rows 3)      ; the IT timing walk's RowMap
//!     (write :format0 true)   ; the canonical writer's own output
//!     (times "3FE0…" …)       ; Playhead.at per seconds bit pattern
//!     (at :tick 46126080)     ; the same answer, asked by tick
//!     (snap :tick N :grid q16 :swing "3FE0…")
//!     (dump)                  ; the document's timeline tier, re-printed
//!     (build :kind mid)       ; its inline tier through the writer
//!
//! The split is pacer's: SHAPE is the schema's, and what stays here is
//! what a form-at-a-time schema cannot see — document order, the WIDTH of
//! a bit pattern, which verbs a case's fixture makes meaningful, and "at
//! least one directive".
//!
//!     (plan retime :args (a :sel (s :lanes [flash]) :delta 46126080))
//!     (export-score :lines 12)
//!
//! The manifest declares nothing this half does not implement. It used to
//! declare one thing — `timing`, which echoed the derived `TimeMap` for
//! the studio's timing provider — and since pstudio is not a host, that
//! verb had no implementation and never would: the runner answered
//! `UNRUN timing` and FAILED any case that asked for it. A declared verb
//! that can only ever fail is a trap rather than a vocabulary, so it is
//! gone from `schema/tempura-corpus.sjon` (2026-09-21), and `(echo …)`
//! at the top of every document case is what it would have printed.
//!
//! `.unrun` STAYS as the fallback for a head the manifest declares and
//! this half has not caught up with: an `unknown_form` is an SJON error
//! and never reaches the dispatch, so without it a newly declared verb
//! would silently be a no-op case. Meeting one is `UNRUN <directive>` and
//! a FAILED case; an unrun case is never reported green.
//!
//! ## The document
//!
//! The verbs below `(write …)` ask about a DOCUMENT, and a case loads one
//! only when its harness asks — so the cores' own goldens, which ask
//! about bytes and nothing else, carry no timeline they never mention.
//! Where the document comes from is the input's business:
//!
//!   - `doc.sjon` IS one, read through `doc/fromSjon.zig` with a resolver
//!     rooted at the case's own directory (an anchor's `:file` is
//!     resolved relative to the document, plan 02);
//!   - `song.mid` / `song.it` goes through `doc/pipeline.zig`'s `dump` —
//!     the same function `tempura dump` runs — so the timeline tier it
//!     gets is the one plan 04's five reconciliation rules produced for
//!     it: the author's own restored text when the file carries an
//!     essence its hashes still agree with, and the skeleton rule 1
//!     derives when it carries nothing. The rule, the conductor's
//!     verdict and one verdict per lane record then ride in the golden as
//!     `(reconciled …)`, which is what lets a `residue-*` case be a
//!     corpus case at all.
//!
//! The derivation's own canonical text is then printed ONCE, at the top,
//! as `(echo …)`: the tempo segments with their exact bit patterns, the
//! meters, the bar table, the length, the sections, the cues and the
//! lanes, then everything the load and the derivation complained of.
//! That header is what plan 03's phase-3 red compares across the three
//! `tempo-three-conductors*` cases, and a test at the bottom of this file
//! asserts the three are byte-identical.
//!
//! ## The golden
//!
//! Canonical down to the byte. The header line names the verb that wrote
//! it, then the fixture is pinned by length and hash — so a fixture that
//! drifts moves every golden that describes it — and then one form per
//! directive, in the order the harness spelled them:
//!
//!     ; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
//!     (fixture :file "song.mid" :bytes 74 :sha256 "…")
//!     (read
//!       (smf :format 0 :division 96 :smpte none :tracks 1 :events 4 :running-status 0 :foreign 0)
//!       (diag :code 26 :severity info :start 22 :end 28 :message "…"))
//!     (roundtrip
//!       (rung1 :ok true :sha256 "…")
//!       (rung2 :ok true))
//!     (write :format0 true :sha256 "…" :bytes 74 :tracks 1 :events 9)
//!
//! An `.it` case reads the same way with `(it :title … :speed … :tempo …
//! :orders N :patterns N :instruments N :samples N :message-len N :tmpu
//! B)` in place of the `(smf …)` child, answers `(write …)` with the
//! module's own counts (`:format0` is the SMF merge and is refused), and
//! adds the walk:
//!
//!     (walk :max-rows 1048576
//!       (row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)
//!       (segment :tick 0 :tempo 125)
//!       (onset :ch 0 :tick 0 :note 60)
//!       (total :ticks 24 :loop-row 0))
//!
//! Diagnostics carry the NUMERIC code, never the name: `Diag.Code`'s
//! ordinal is the wire (it rides the `'TPDG'` blob and the CLI's JSON),
//! and it is APPEND-ONLY from E3 — so a code appended at the end never
//! disturbs a golden, while a reorder would move every one of them at
//! once and say so loudly here. The names stay covered by `zig build
//! audit-diagnostics`, which refuses a code no test spells out. A
//! diagnostic also carries its severity, its span into the bytes that
//! were read, and its message verbatim. A row map echoes at most 4096
//! rows and 4096 onsets and then says how many it left out, so a runaway
//! case cannot produce a golden nobody can read.
//!
//! `(rung1 :ok true)` is `write(read(bytes)) == bytes` and holds for
//! every file tempura's own canonical writer produced; `(rung2 :ok true)`
//! is `read(write(read(bytes)))` equal to `read(bytes)` event for event
//! (`.mid`) or field for field with every pass-through region byte-equal
//! (`.it`). A FOREIGN fixture — one this writer would never have
//! produced, a SMPTE division it never spells or a command byte no IT
//! effect names — is what rung 2 is FOR (plan 09), and its golden pins
//! `(rung1 :ok false)` beside it. That flag is a recorded fact, not a
//! failed gate: the verdict is byte-equality with the golden, and the
//! case's own `times.sjon` says why the writer normalised the file.
//! `(write)` beside them hashes what it normalised it to.
//!
//! A document case adds the `(echo …)` header and one form per query:
//!
//!     (fixture :file "doc.sjon" :bytes 806 :sha256 "…")
//!     (echo
//!       (segment :tick 0 :us 480000 :tps "4196E93C00000000" :start-sec "0000000000000000")
//!       (meter :tick 0 :sig [4 4] :first-bar 0)
//!       (bars :count 2 :last-start 184504320)
//!       (length :tick 184504320 :end hold :loop-secs "3FF7AE147AE147AE"))
//!     (at :seconds "3FDEB851EB851EB8" :tick 46126080 :bar 0 :beat 1 :sub 0
//!         :sections [] :prev-cue none :next-cue none)
//!     (at :tick 46126080 :bar 0 :beat 1 :sub 0 :sections [] :prev-cue none :next-cue none)
//!     (snapped :tick 103783680)
//!     (built :kind mid :len 76 :sha256 "…"
//!       (rung1 :ok true))
//!     (dump :bytes 86 :sha256 "…")
//!     ;| (timeline :length 1bar :conductor song)
//!
//! `:seconds` is present exactly when the question was asked in seconds,
//! which is what tells the two position queries apart in a golden read on
//! its own; `:order :row :tick-in-row` follow when an IT anchor conducts,
//! because only then is there a tracker position to report. A seconds
//! value no clock can answer — a NaN, an infinity — comes back as
//! `(at :seconds "…" :refused non-finite-time)` rather than a position
//! nobody asked for.
//!
//! `(dump …)` hashes the TIMELINE tier alone — the roots that are not
//! `midi/` or `it/` forms — and then writes it out line by line behind a
//! `;| ` marker: the text is what a reviewer reads, and a comment prefix
//! is what keeps a golden one SJON document rather than two. `(built …)`
//! is the document's inline tier through the canonical writer, which is
//! the half of plan 09's rung 3 a bridge can answer; a document with no
//! tier answers `(built :kind K :unsupported "…")` rather than inventing
//! a file.
//!
//! Per-case defects (a missing file, a malformed harness, a directive the
//! fixture cannot answer) fail the case and the run continues —
//! collection over abort, the SJON discipline. Only resource exhaustion
//! aborts.

const std = @import("std");
const sjon = @import("sjon");
const Diag = @import("Diag.zig");
const Schema = @import("Schema.zig");
const smf = @import("smf/smf.zig");
const itf = @import("itf/itf.zig");
const doc = @import("doc/doc.zig");
const FsStore = @import("FsStore.zig");
const edit_engine = @import("edit/edit.zig");
const exporter = @import("export/export.zig");
const time = @import("time/time.zig");

const Grid = time.Grid;
const Playhead = time.Playhead;
const Derived = time.derive.Derived;

const Io = std.Io;
const Allocator = std.mem.Allocator;
const Ast = sjon.Ast;
const NodeIndex = Ast.NodeIndex;
const Sha256 = std.crypto.hash.sha2.Sha256;

/// This module's error set: rendering a golden can only fail the way any
/// allocation fails. Everything a case gets wrong is a report line.
pub const Error = error{OutOfMemory};

/// Corpus inputs are small: a harness is a page of text and a fixture is
/// a few kilobytes. Anything bigger is a mistake, not a corpus case.
const MAX_FILE_BYTES: usize = 1 << 20;

/// How many rows and onsets a walk echo carries before it elides the
/// rest. A runaway case plays a million rows; a golden nobody can read
/// is not evidence.
const MAX_ROWS_ECHOED: usize = 4096;
const MAX_ONSETS_ECHOED: usize = 4096;

const GENERATED_HEADER =
    "; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.\n";

pub fn main(init: std.process.Init) !u8 {
    const arena = init.arena.allocator();
    const gpa = init.gpa;
    const io = init.io;

    var stderr_buf: [4096]u8 = undefined;
    var stderr_file = Io.File.stderr();
    var stderr_writer = stderr_file.writer(io, &stderr_buf);
    const out = &stderr_writer.interface;
    defer out.flush() catch {};

    const args = try init.minimal.args.toSlice(arena);
    const cmd = parseArgs(args[1..]) orelse {
        try out.print("usage: corpus-runner <corpus-dir> [--update]\n", .{});
        return 2;
    };
    const root = cmd.root;
    const update = cmd.update;

    var dir = Io.Dir.cwd().openDir(io, root, .{ .iterate = true }) catch |err| {
        try out.print("corpus: cannot open `{s}`: {s}\n", .{ root, @errorName(err) });
        return 1;
    };
    defer dir.close(io);
    const names = try caseNames(arena, io, dir);
    if (names.len == 0) {
        // The corpus IS the gate: an empty one means the checkout is
        // broken, not that there is nothing to disagree about.
        try out.print("corpus: no cases under `{s}`\n", .{root});
        return 1;
    }

    // One preloaded harness bundle for the whole walk — the manifest is
    // parsed and aggregate-validated once, not once per case, and it
    // outlives every case's validation result.
    var harness_schema = try Schema.loadCorpus(gpa);
    defer harness_schema.deinit();

    // …and one preloaded TIMELINE bundle beside it, for the cases whose
    // input is a document. Two bundles, never composed: a harness file
    // is a script of verbs and not a document, so composing them would
    // only put every document's vocabulary within reach of a typo in a
    // `times.sjon` and the harness's own `read`, `write`, `plan`, `snap`
    // and `roundtrip` within reach of a document. `src/Schema.zig`'s
    // "never composed" test is the proof: those five are unreachable in
    // the timeline bundle and all five resolve in a composed one.
    var doc_schema = try Schema.load(gpa);
    defer doc_schema.deinit();

    var failed: usize = 0;
    var updated: usize = 0;
    for (names) |name| {
        switch (try runCase(gpa, &harness_schema, &doc_schema, io, out, root, name, update)) {
            .ok => {},
            .updated => updated += 1,
            .failed => failed += 1,
        }
    }

    if (update) {
        try out.print(
            "corpus: {d} case(s), {d} regenerated, {d} failed\n",
            .{ names.len, updated, failed },
        );
    } else {
        try out.print("corpus: {d} case(s), {d} failed\n", .{ names.len, failed });
    }
    return if (failed == 0) 0 else 1;
}

/// What the command line asked for. `parseArgs` answers null for a usage
/// error: no directory, or a second one.
const Command = struct { root: []const u8, update: bool };

fn parseArgs(args: []const [:0]const u8) ?Command {
    var root: ?[]const u8 = null;
    var update = false;
    for (args) |arg| {
        if (std.mem.eql(u8, arg, "--update")) {
            update = true;
        } else if (root == null) {
            root = arg;
        } else {
            return null;
        }
    }
    return .{ .root = root orelse return null, .update = update };
}

/// The case directories in `dir`, sorted — filesystem iteration order is
/// unspecified and the report has to be stable. A hidden directory is not
/// a case. The names live in `arena`.
fn caseNames(arena: Allocator, io: Io, dir: Io.Dir) ![]const []const u8 {
    var names: std.ArrayList([]const u8) = .empty;
    var it = dir.iterate();
    while (try it.next(io)) |entry| {
        if (entry.kind != .directory) continue;
        if (entry.name.len == 0 or entry.name[0] == '.') continue;
        try names.append(arena, try arena.dupe(u8, entry.name));
    }
    std.mem.sort([]const u8, names.items, {}, nameBefore);
    return names.items;
}

fn nameBefore(_: void, x: []const u8, y: []const u8) bool {
    return std.mem.lessThan(u8, x, y);
}

const Outcome = enum { ok, updated, failed };

fn runCase(
    gpa: Allocator,
    harness_schema: *const Schema,
    doc_schema: *const Schema,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
    update: bool,
) !Outcome {
    // Everything this case allocates dies together.
    var case_arena = std.heap.ArenaAllocator.init(gpa);
    defer case_arena.deinit();
    const arena = case_arena.allocator();

    const harness_src = readCaseFile(
        arena,
        io,
        out,
        root,
        name,
        "times.sjon",
    ) orelse return .failed;
    const directives = (try parseHarness(
        arena,
        gpa,
        harness_schema,
        out,
        name,
        harness_src,
    )) orelse return .failed;
    const fixture = (try findFixture(arena, io, out, root, name)) orelse return .failed;

    var aw: Io.Writer.Allocating = .init(arena);
    defer aw.deinit();
    const rep: Report = .{ .out = out, .name = name };
    const env: Env = .{ .io = io, .schema = doc_schema, .root = root, .name = name };
    if (!try renderCase(gpa, arena, env, &aw.writer, fixture, directives, rep)) return .failed;
    const actual = aw.toOwnedSlice() catch return error.OutOfMemory;

    const expected_path = try std.fs.path.join(arena, &.{ root, name, "expected.sjon" });
    if (update) {
        Io.Dir.cwd().writeFile(io, .{ .sub_path = expected_path, .data = actual }) catch |err| {
            try out.print(
                "corpus: {s}: cannot write expected.sjon: {s}\n",
                .{ name, @errorName(err) },
            );
            return .failed;
        };
        try out.print("corpus: {s}: regenerated\n", .{name});
        return .updated;
    }

    const expected = readCaseFile(
        arena,
        io,
        out,
        root,
        name,
        "expected.sjon",
    ) orelse return .failed;
    const diff = firstDifference(expected, actual) orelse return .ok;
    try reportMismatch(out, name, diff);
    return .failed;
}

fn readCaseFile(
    arena: Allocator,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
    file: []const u8,
) ?[:0]u8 {
    const path = std.fs.path.join(arena, &.{ root, name, file }) catch |err| {
        out.print(
            "corpus: {s}: cannot join path for {s}: {s}\n",
            .{ name, file, @errorName(err) },
        ) catch {};
        return null;
    };
    return Io.Dir.cwd().readFileAllocOptions(
        io,
        path,
        arena,
        .limited(MAX_FILE_BYTES),
        .of(u8),
        0,
    ) catch |err| {
        out.print("corpus: {s}: cannot read {s}: {s}\n", .{ name, file, @errorName(err) }) catch {};
        return null;
    };
}

// ---------------------------------------------------------------------------
// The fixture
// ---------------------------------------------------------------------------

/// Which core reads a case's fixture. The file name chooses it.
/// `doc` is a timeline document and reads through `doc/fromSjon.zig`.
const FixtureKind = enum { smf, it, doc };

/// The case's pinned input: which file it came from, and its bytes.
///
/// Sentinel-terminated because one of the three IS source text and SJON
/// reads a `[:0]const u8`; the two binary cores take the slice and never
/// look at the terminator.
const Fixture = struct {
    file: []const u8,
    bytes: [:0]const u8,
    kind: FixtureKind,
};

/// The three names a case's input may carry, in the order they are
/// looked for. `doc.sjon` goes FIRST so that a case which is a document
/// arranged around a file — the anchored half, whose `song.*` sits
/// beside it as the anchor's referent — is read as the document it is
/// rather than as the file it names.
fn findFixture(
    arena: Allocator,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
) !?Fixture {
    const candidates = [_]struct { file: []const u8, kind: FixtureKind }{
        .{ .file = "doc.sjon", .kind = .doc },
        .{ .file = "song.mid", .kind = .smf },
        .{ .file = "song.it", .kind = .it },
    };
    for (candidates) |c| {
        const path = try std.fs.path.join(arena, &.{ root, name, c.file });
        const bytes = Io.Dir.cwd().readFileAllocOptions(
            io,
            path,
            arena,
            .limited(MAX_FILE_BYTES),
            .of(u8),
            0,
        ) catch continue;
        return .{ .file = c.file, .bytes = bytes, .kind = c.kind };
    }
    try out.print("corpus: {s}: no fixture (expected doc.sjon, song.mid or song.it)\n", .{name});
    return null;
}

// ---------------------------------------------------------------------------
// The harness — an ordered script of directives
// ---------------------------------------------------------------------------

/// Which file a `(build …)` writes. `mid` rather than `smf` because a
/// case reads as the file it produces.
const BuildKind = enum { mid, it };

/// What a `(build …)` asks for: the kind, and the one renderer switch a
/// golden needs to show (plan 08's `--cc`, without which a native curve
/// lane has no controller to render onto and says `render_cc_missing`).
const BuildAsk = struct { kind: BuildKind, cc: ?u7 };

/// What an `(export-score …)` asks for: how much of the text to show,
/// and the key budget to show it under.
const ScoreAsk = struct { lines: u32, max_keys: u32 };

/// What a `(snap …)` asks for: `Playhead.snap`'s three arguments.
const SnapAsk = struct { tick: i64, grid: Playhead.SnapGrid, swing: f64 };

/// One directive, executed in document order against the case's fixture.
const Directive = union(enum) {
    /// What the core made of the bytes, and everything it complained of.
    read,
    /// Rungs 1 and 2 of plan 09's ladder.
    roundtrip,
    /// The IT timing walk's `RowMap`, bounded by `max_rows`.
    walk: u32,
    /// The canonical writer's own output, with its switches.
    write: struct { format0: bool },
    /// One `Playhead.at` per seconds value, in the order written.
    times: []const f64,
    /// The same answer, asked by tick.
    at: i64,
    /// `Playhead.snap` under the meter in force.
    snap: SnapAsk,
    /// The document, re-printed: its timeline tier, verbatim.
    dump,
    /// The document as a file: its inline tier through the canonical
    /// writer, or — for a NATIVE document — plan 08's renderers and plan
    /// 04's carriers through `doc/pipeline.zig`'s `build`.
    build: BuildAsk,
    /// One edit operation planned and applied: the operation as the
    /// edit engine's own `--op` JSON, built from the harness's `:args`.
    plan: []const u8,
    /// The document as a pacer score: how many lines to show, and the
    /// key budget to show them under.
    export_score: ScoreAsk,
    /// A head the manifest declares and this half does not implement.
    /// It carries the head so the report can name it.
    unrun: []const u8,

    /// Whether answering this directive needs the case's DOCUMENT —
    /// which is what decides whether a case loads one at all. A case
    /// that asks only about bytes never loads a document, so the cores'
    /// own goldens say nothing about one.
    fn needsDocument(self: Directive) bool {
        return switch (self) {
            .times, .at, .snap, .dump, .build, .plan, .export_score => true,
            .read, .roundtrip, .walk, .write, .unrun => false,
        };
    }
};

/// Read `times.sjon`. Null = the case is void (already reported).
///
/// SHAPE is the schema's: the source is validated against the preloaded
/// harness vocabulary, so an unknown head, a `:max-rows` past the walk's
/// ceiling or a `:format0` that is not a boolean is an SJON diagnostic
/// with a SPAN before a single field is read. What stays here is what a
/// form-at-a-time schema cannot see: document ORDER, "at least one
/// directive", and which heads this half implements at all.
fn parseHarness(
    arena: Allocator,
    gpa: Allocator,
    harness_schema: *const Schema,
    out: *Io.Writer,
    name: []const u8,
    src: [:0]const u8,
) !?[]const Directive {
    // Validation never aborts on malformed input (collection over
    // abort) — parse errors arrive as diagnostics alongside schema ones.
    var v = Schema.validate(gpa, harness_schema, src) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
    };
    defer v.deinit();
    if (v.hasErrors()) {
        try out.print("corpus: {s}: times.sjon does not validate:\n", .{name});
        for (v.diagnostics) |d| {
            if (d.severity != .err) continue;
            try out.print("  {s}: {d}..{d}: {s}\n", .{
                @tagName(d.code),
                d.span.start,
                d.span.end,
                d.message,
            });
        }
        return null;
    }
    const tree = &v.tree;
    const view: sjon.EffectiveView.EffectiveView = .init(&v.tree, &v.materialized_defaults);

    var directives: std.ArrayList(Directive) = .empty;
    for (tree.root) |idx| {
        if (tree.tagOf(idx) != .form) {
            // A bare value at the root is not a form, so no `(form …)`
            // declaration governs it and the validator has nothing to
            // say about it.
            try out.print(
                "corpus: {s}: times.sjon: only directive forms are allowed at the root\n",
                .{name},
            );
            return null;
        }
        const d = (try readDirective(arena, &view, tree, idx, out, name)) orelse return null;
        try directives.append(arena, d);
    }

    if (directives.items.len == 0) {
        try out.print(
            "corpus: {s}: times.sjon: no directives (a case has to ask something)\n",
            .{name},
        );
        return null;
    }
    return directives.items;
}

/// One root form as the directive it spells. Its SHAPE was the schema's;
/// what is read here is the author's literal or the manifest's default,
/// through the view. Null = the case is void (already reported).
fn readDirective(
    arena: Allocator,
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    idx: NodeIndex,
    out: *Io.Writer,
    name: []const u8,
) !?Directive {
    const hdr = tree.formHeader(idx);
    const head = hdr.head;
    if (std.mem.eql(u8, head, "read")) return .read;
    if (std.mem.eql(u8, head, "roundtrip")) return .roundtrip;
    if (std.mem.eql(u8, head, "walk"))
        return .{ .walk = @intCast(effInt(view, tree, idx, "max-rows")) };
    if (std.mem.eql(u8, head, "write"))
        return .{ .write = .{ .format0 = effBool(view, tree, idx, "format0") } };
    if (std.mem.eql(u8, head, "times")) {
        const secs = (try readTimes(arena, tree, hdr.children, out, name)) orelse return null;
        return .{ .times = secs };
    }
    if (std.mem.eql(u8, head, "at"))
        return .{ .at = @intCast(effInt(view, tree, idx, "tick")) };
    if (std.mem.eql(u8, head, "snap")) {
        const ask = (try readSnap(view, tree, idx, out, name)) orelse return null;
        return .{ .snap = ask };
    }
    if (std.mem.eql(u8, head, "dump")) return .dump;
    if (std.mem.eql(u8, head, "plan")) {
        const json = (try opJson(arena, tree, idx, out, name)) orelse return null;
        return .{ .plan = json };
    }
    if (std.mem.eql(u8, head, "export-score")) return .{ .export_score = .{
        .lines = @intCast(effInt(view, tree, idx, "lines")),
        .max_keys = @intCast(effInt(view, tree, idx, "max-keys")),
    } };
    if (std.mem.eql(u8, head, "build")) return .{ .build = .{
        .kind = std.meta.stringToEnum(BuildKind, effSym(view, tree, idx, "kind")).?,
        .cc = if (optInt(view, tree, idx, "cc")) |n| @intCast(n) else null,
    } };
    // `unknown_form` is an error and an erroring document never reaches
    // here, so the head is one the manifest declares — and one P107's
    // documents half implements.
    return .{ .unrun = try arena.dupe(u8, head) };
}

/// The seconds a `(times …)` asks about, as bit patterns in the order
/// written. Their WIDTH is this file's check: a string carries none, so
/// the manifest cannot state it (its own header says so). Null = the
/// case is void (already reported).
fn readTimes(
    arena: Allocator,
    tree: *const Ast.Tree,
    children: []const NodeIndex,
    out: *Io.Writer,
    name: []const u8,
) !?[]const f64 {
    var secs: std.ArrayList(f64) = .empty;
    for (children) |child| {
        if (tree.tagOf(child) != .string) continue;
        const bits_ = parseBits(tree.stringText(child)) orelse {
            try reportBadBits(out, name, tree.stringText(child));
            return null;
        };
        try secs.append(arena, @bitCast(bits_));
    }
    if (secs.items.len == 0) {
        try out.print("corpus: {s}: times.sjon: (times …) with no seconds asks nothing\n", .{name});
        return null;
    }
    return secs.items;
}

/// A `(snap …)`'s ask. Null = its swing is not a bit pattern (reported).
fn readSnap(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    idx: NodeIndex,
    out: *Io.Writer,
    name: []const u8,
) !?SnapAsk {
    const swing_text = effStr(view, tree, idx, "swing");
    const swing_bits = parseBits(swing_text) orelse {
        try reportBadBits(out, name, swing_text);
        return null;
    };
    return .{
        .tick = @intCast(effInt(view, tree, idx, "tick")),
        // The member set is the schema's, and it is exactly
        // `Playhead.SnapGrid`'s field list — so a name that got past
        // validation converts, and the test below is what keeps the two
        // spellings from drifting.
        .grid = std.meta.stringToEnum(Playhead.SnapGrid, effSym(view, tree, idx, "grid")).?,
        .swing = @bitCast(swing_bits),
    };
}

/// The effective `:key` on `form` as a non-negative integer — the
/// author's literal when written, else the manifest's `:default` (a
/// default has ONE spelling, and it is the schema's). Every key read
/// this way is declared `:integer true` with bounds, so the conversion
/// below is exhaustive by validation rather than by hope.
fn effInt(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) u64 {
    const ev = view.getEffectiveValue(form, key).?;
    const n: f64 = switch (ev) {
        .author => |node| switch (tree.tagOf(node)) {
            .number => tree.numberOf(node),
            .number_i64 => @floatFromInt(tree.numberI64Of(node)),
            .number_u64 => @floatFromInt(tree.numberU64Of(node)),
            else => unreachable,
        },
        .default => |entry| switch (entry.value) {
            .number => |x| x,
            .integer_i64 => |x| @floatFromInt(x),
            .integer_u64 => |x| @floatFromInt(x),
            else => unreachable,
        },
    };
    std.debug.assert(n >= 0 and n == @floor(n));
    return @intFromFloat(n);
}

/// The same, for a key that is optional AND has no default: absent is a
/// real answer, which `effInt`'s `.?` would turn into a panic.
fn optInt(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) ?u64 {
    _ = view.getEffectiveValue(form, key) orelse return null;
    return effInt(view, tree, form, key);
}

/// The effective `:key` on `form` as a string — the author's literal, or
/// the manifest's `:default`. Every key read this way is declared with a
/// string underlying and a default, so both arms are exhaustive by
/// validation.
fn effStr(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) []const u8 {
    const ev = view.getEffectiveValue(form, key).?;
    return switch (ev) {
        .author => |node| tree.stringText(node),
        .default => |entry| switch (entry.value) {
            .string => |s| s,
            else => unreachable,
        },
    };
}

/// The effective `:key` on `form` as a symbol. Every key read this way is
/// declared with a member set and no default, so the author wrote it.
fn effSym(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) []const u8 {
    const ev = view.getEffectiveValue(form, key).?;
    return switch (ev) {
        .author => |node| tree.symbolText(node),
        .default => unreachable,
    };
}

/// A 16-hex-digit f64 bit pattern, or null when it is not one.
///
/// The WIDTH is the point: a string carries none, so `"3FE"` would read
/// as a perfectly good small integer and name a denormal nobody meant.
/// Either case of letters is read, because a golden's own digests are
/// lowercase and a harness author will mix them.
fn parseBits(text: []const u8) ?u64 {
    if (text.len != 16) return null;
    for (text) |c| {
        if (!std.ascii.isHex(c)) return null;
    }
    return std.fmt.parseInt(u64, text, 16) catch null;
}

fn reportBadBits(out: *Io.Writer, name: []const u8, text: []const u8) !void {
    try out.print(
        "corpus: {s}: times.sjon: a bit pattern is 16 hex digits; \"{s}\" is not one\n",
        .{ name, text },
    );
}

/// The effective `:key` on `form` as a boolean, the same way.
fn effBool(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) bool {
    const ev = view.getEffectiveValue(form, key).?;
    return switch (ev) {
        .author => |node| tree.tagOf(node) == .boolean_true,
        .default => |entry| switch (entry.value) {
            .boolean => |b| b,
            else => unreachable,
        },
    };
}

/// A `(plan <op> :args (a …))` directive as the edit engine's own `--op`
/// JSON.
///
/// The harness spells an operation in SJON and the engine reads it as
/// JSON (`edit/edit.zig`'s header is the grammar), so one of the two has
/// to be translated and this is the seam. SJON is the harness's language
/// — a case is hand-authored and `sjon fmt` has to leave it alone — and
/// JSON is the engine's, because that is the spelling a CLI passes on
/// `--op` and the one a host would send. Nothing is INTERPRETED here: the
/// keys, the numbers and the symbols cross unchanged and the engine
/// answers for every one of them, with spans.
///
/// The `:args` form's HEAD is a marker and is dropped — the schema
/// declares `:args` opaque, so it needs a head to be a form at all and
/// nothing reads it. Null = the case is void (already reported).
fn opJson(
    arena: Allocator,
    tree: *const Ast.Tree,
    form: NodeIndex,
    out: *Io.Writer,
    name: []const u8,
) Error!?[]const u8 {
    const hdr = tree.formHeader(form);

    var op: ?[]const u8 = null;
    var args: ?NodeIndex = null;
    for (hdr.children) |child| switch (tree.tagOf(child)) {
        .symbol => if (op == null) {
            op = tree.symbolText(child);
        },
        .kvpair => {
            const kv = tree.kvpairHeader(child);
            if (std.mem.eql(u8, kv.key, "args")) args = kv.value;
        },
        else => {},
    };

    const head = op orelse {
        out.print("corpus: {s}: times.sjon: (plan …) names no operation\n", .{name}) catch {};
        return null;
    };

    var buf: Io.Writer.Allocating = .init(arena);
    try p(&buf.writer, "{{\"op\":\"{s}\"", .{head});
    if (args) |node| {
        if (tree.tagOf(node) != .form) {
            out.print(
                "corpus: {s}: times.sjon: (plan …)'s :args is a form of keys\n",
                .{name},
            ) catch {};
            return null;
        }
        for (tree.formHeader(node).children) |child| {
            if (tree.tagOf(child) != .kvpair) continue;
            const kv = tree.kvpairHeader(child);
            try p(&buf.writer, ",\"{s}\":", .{kv.key});
            try jsonOfNode(&buf.writer, tree, kv.value);
        }
    }
    try pw(&buf.writer, "}");
    return buf.toOwnedSlice() catch return error.OutOfMemory;
}

/// One SJON value as JSON. A symbol becomes a string, because every
/// symbol the operation grammar takes (`"kinds":["note"]`, `"what":
/// "lane"`, a lane's name) is a string there; a united number would be a
/// position, and the grammar takes TICKS, so a unit is refused rather
/// than silently dropped.
fn jsonOfNode(w: *Io.Writer, tree: *const Ast.Tree, node: NodeIndex) Error!void {
    switch (tree.tagOf(node)) {
        .number => try p(w, "{d}", .{tree.numberOf(node)}),
        .number_i64 => try p(w, "{d}", .{tree.numberI64Of(node)}),
        .number_u64 => try p(w, "{d}", .{tree.numberU64Of(node)}),
        .boolean_true => try pw(w, "true"),
        .boolean_false => try pw(w, "false"),
        .string => try jsonString(w, tree.stringText(node)),
        .symbol => try jsonString(w, tree.symbolText(node)),
        .keyword => try jsonString(w, tree.keywordText(node)),
        .vector => {
            try pw(w, "[");
            for (tree.vectorElements(node), 0..) |item, i| {
                if (i > 0) try pw(w, ",");
                try jsonOfNode(w, tree, item);
            }
            try pw(w, "]");
        },
        .form => {
            // A nested form is a nested OBJECT — which is how a `"sel"`
            // is spelled: `(plan remove :args (a :sel (s :lanes [flash])))`.
            try pw(w, "{");
            var first = true;
            for (tree.formHeader(node).children) |child| {
                if (tree.tagOf(child) != .kvpair) continue;
                const kv = tree.kvpairHeader(child);
                if (!first) try pw(w, ",");
                first = false;
                try p(w, "\"{s}\":", .{kv.key});
                try jsonOfNode(w, tree, kv.value);
            }
            try pw(w, "}");
        },
        // Everything else — a united number above all — is not part of
        // the operation grammar, and `null` is what the engine will
        // complain about, by name and with a span.
        else => try pw(w, "null"),
    }
}

fn jsonString(w: *Io.Writer, text: []const u8) Error!void {
    try pw(w, "\"");
    for (text) |c| switch (c) {
        '"' => try pw(w, "\\\""),
        '\\' => try pw(w, "\\\\"),
        '\n' => try pw(w, "\\n"),
        '\r' => try pw(w, "\\r"),
        '\t' => try pw(w, "\\t"),
        else => if (c < 0x20) try p(w, "\\u{x:0>4}", .{c}) else try pw(w, &[_]u8{c}),
    };
    try pw(w, "\"");
}

// ---------------------------------------------------------------------------
// Canonical rendering — the byte-pinned format
// ---------------------------------------------------------------------------

/// Where a defect that VOIDS a golden is reported: the case's name and
/// the run's report writer. `out` is null in tests, which have no report
/// to write and assert on the return value instead.
const Report = struct {
    out: ?*Io.Writer,
    name: []const u8,

    fn say(self: Report, comptime fmt: []const u8, args: anytype) void {
        const out = self.out orelse return;
        out.print("corpus: {s}: " ++ fmt, .{self.name} ++ args) catch {};
    }
};

/// `Io.Writer.Allocating` fails one way only, and a golden half-written
/// is a golden not written: every print goes through here so the error
/// set stays `Error`.
fn p(w: *Io.Writer, comptime fmt: []const u8, args: anytype) Error!void {
    w.print(fmt, args) catch return error.OutOfMemory;
}

fn pw(w: *Io.Writer, bytes: []const u8) Error!void {
    w.writeAll(bytes) catch return error.OutOfMemory;
}

/// The SHA-256 of `bytes` as 64 lowercase hex digits. What the goldens
/// pin a byte string by — the fixture, the rewrite, the merged file —
/// and what x86_64, aarch64 and wasm32 must agree on.
fn writeDigest(w: *Io.Writer, bytes: []const u8) Error!void {
    var digest: [Sha256.digest_length]u8 = undefined;
    Sha256.hash(bytes, &digest, .{});
    for (digest) |b| try p(w, "{x:0>2}", .{b});
}

/// The severity a golden spells. `Diag.Severity.err` is `error` in text:
/// the enum's name is a Zig keyword and the golden is not Zig.
fn severityName(s: Diag.Severity) []const u8 {
    return switch (s) {
        .err => "error",
        .warning => "warning",
        .info => "info",
    };
}

/// One `(diag …)` child per entry, each on its own line at `indent`.
/// Nothing at all when the list is empty, so a clean read is one line.
///
/// False = a message carries a control byte and the golden is void
/// (a diagnostic can quote a file's own bytes — a chunk tag, a name —
/// and an unprintable byte in a golden is not reviewable text).
fn renderDiags(
    w: *Io.Writer,
    indent: []const u8,
    diags: *const Diag.List,
    rep: Report,
) Error!bool {
    for (diags.items()) |d| {
        try p(w, "\n{s}(diag :code {d} :severity {s} :start {d} :end {d} :message \"", .{
            indent,
            @intFromEnum(d.code),
            severityName(d.severity),
            d.span.start,
            d.span.end,
        });
        for (d.message) |b| {
            if (b < 0x20) {
                rep.say("control byte in a diagnostic message — not renderable\n", .{});
                return false;
            }
            if (b == '"' or b == '\\') try p(w, "\\", .{});
            try p(w, "{c}", .{b});
        }
        try pw(w, "\")");
    }
    return true;
}

/// A file's own text — a module title, a chunk tag — inside a golden's
/// string. Same escaping and the same control-byte refusal.
fn renderText(w: *Io.Writer, text: []const u8, rep: Report) Error!bool {
    for (text) |b| {
        if (b < 0x20) {
            rep.say("control byte in a name — not renderable\n", .{});
            return false;
        }
        if (b == '"' or b == '\\') try p(w, "\\", .{});
        try p(w, "{c}", .{b});
    }
    return true;
}

/// Render one case's whole golden. False = a defect that voids it
/// (already reported): a directive the fixture cannot answer, a
/// directive this half does not implement, an unrenderable byte.
fn renderCase(
    gpa: Allocator,
    arena: Allocator,
    env: Env,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    rep: Report,
) Error!bool {
    try pw(w, GENERATED_HEADER);
    // The fixture is pinned by length and hash before anything is asked
    // of it: `zig build fixtures` regenerating different bytes moves
    // every golden that describes them, which is the drift showing.
    try p(w, "(fixture :file \"{s}\" :bytes {d} :sha256 \"", .{ fixture.file, fixture.bytes.len });
    try writeDigest(w, fixture.bytes);
    try pw(w, "\")\n");

    // A case loads a DOCUMENT only when its harness asks something of
    // one. That is what keeps the cores' own goldens — which ask about
    // bytes and nothing else — free of a timeline they never mention,
    // and it is why the echo header can sit at the top of every document
    // case rather than being threaded through the directive loop.
    var loaded: ?Loaded = null;
    defer if (loaded) |*l| l.deinit();
    for (directives) |d| {
        if (!d.needsDocument()) continue;
        loaded = (try loadDocument(gpa, arena, env, fixture)) orelse return false;
        if (!try renderEcho(arena, w, &loaded.?, rep)) return false;
        break;
    }
    const doc_ptr: ?*Loaded = if (loaded) |*l| l else null;

    return switch (fixture.kind) {
        .smf => try renderSmfCase(gpa, arena, w, fixture, directives, doc_ptr, rep),
        .it => try renderItCase(gpa, arena, w, fixture, directives, doc_ptr, rep),
        .doc => try renderDocCase(gpa, w, fixture, directives, doc_ptr, rep),
    };
}

/// A case whose input IS a document. Every directive it can answer is
/// the document half's; a head that asks about BYTES has none to read
/// here and voids the golden, which is the same verdict `(walk …)` gets
/// on a `.mid`. False = a defect (already reported).
fn renderDocCase(
    gpa: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    loaded: ?*Loaded,
    rep: Report,
) Error!bool {
    for (directives) |d| {
        if (d.needsDocument()) {
            // Non-null by construction: `renderCase` loads a document
            // exactly when a directive here needs one.
            if (!try renderDocDirective(gpa, w, d, loaded.?, rep)) return false;
            continue;
        }
        switch (d) {
            .unrun => |head| rep.say(
                "UNRUN {s} — the directive lands with a later part\n",
                .{head},
            ),
            // Every remaining head asks about BYTES, and a document case
            // has none to read: `doc.sjon` is source, not a file either
            // core would recognise.
            else => rep.say("({s} …) needs a song.mid or song.it fixture; this case's is {s}\n", .{
                @tagName(d),
                fixture.file,
            }),
        }
        return false;
    }
    return true;
}

// ---- the SMF half ----

fn renderSmfCase(
    gpa: Allocator,
    arena: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    loaded: ?*Loaded,
    rep: Report,
) Error!bool {
    // Read ONCE for the whole case: every directive asks about the same
    // bytes, and reading them twice would be two answers to gate.
    var r = try smf.read(gpa, fixture.bytes);
    defer r.deinit();

    for (directives) |d| switch (d) {
        .read => if (!try renderSmfRead(w, &r, rep)) return false,
        .roundtrip => {
            if (!try renderSmfRoundtrip(
                gpa,
                arena,
                w,
                fixture.bytes,
                &r.sequence,
                rep,
            )) return false;
        },
        .write => |opts| {
            if (!try renderSmfWrite(gpa, w, &r.sequence, opts.format0, rep)) return false;
        },
        .walk => {
            rep.say("(walk …) needs an .it fixture; this case's is {s}\n", .{fixture.file});
            return false;
        },
        .unrun => |head| {
            rep.say("UNRUN {s} — the directive lands with a later part\n", .{head});
            return false;
        },
        // The document half's verbs, over the document the runner
        // wrapped this fixture in. `renderCase` loaded one exactly
        // because a directive here needs it, and `.unrun` — the one
        // remaining tag that does not — was answered above.
        else => {
            std.debug.assert(d.needsDocument());
            if (!try renderDocDirective(gpa, w, d, loaded.?, rep)) return false;
        },
    };
    return true;
}

/// `(read …)` over a `.mid`: what the core made of the bytes, and
/// everything it complained of.
fn renderSmfRead(w: *Io.Writer, r: *const smf.Result, rep: Report) Error!bool {
    try pw(w, "(read\n  ");
    const seq = &r.sequence;
    try p(w, "(smf :format {d} :division {d} :smpte ", .{
        seq.format,
        seq.division.pulsesPerQuarter(),
    });
    switch (seq.division) {
        // `:division` is always the GRID the file's ticks are on;
        // `:smpte` is what the header actually spelled, so a SMPTE case
        // pins both the file and the conversion.
        .ppq => try pw(w, "none"),
        .smpte => |s| try p(w, "[{d} {d}]", .{ s.fps, s.tpf }),
    }
    try p(w, " :tracks {d} :events {d} :running-status {d} :foreign {d})", .{
        seq.tracks.len,
        seq.eventCount(),
        runningStatusCount(r),
        seq.foreign.len,
    });
    if (!try renderDiags(w, "  ", &r.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// How many events were read ON running status — the one fact about a
/// `.mid`'s LAYOUT that survives into the value, and what
/// `smf-running-status` is a case about.
fn runningStatusCount(r: *const smf.Result) usize {
    var on_running: usize = 0;
    for (r.source_map.tracks) |tm| {
        for (tm.events) |site| {
            if (site.running_status) on_running += 1;
        }
    }
    return on_running;
}

/// `(roundtrip …)` over a `.mid`. Rung 1: the canonical writer's output
/// against the very bytes it is supposed to reproduce. Rung 2: the same
/// events came back, whatever the layout.
fn renderSmfRoundtrip(
    gpa: Allocator,
    arena: Allocator,
    w: *Io.Writer,
    bytes: []const u8,
    sequence: *const smf.Sequence,
    rep: Report,
) Error!bool {
    var rewrite = try smf.write(gpa, sequence, .{});
    defer rewrite.deinit();
    try p(w, "(roundtrip\n  (rung1 :ok {} :sha256 \"", .{std.mem.eql(u8, rewrite.bytes, bytes)});
    try writeDigest(w, rewrite.bytes);
    try pw(w, "\"");
    if (!try renderDiags(w, "    ", &rewrite.diags, rep)) return false;
    try pw(w, ")\n");

    var again = try smf.read(gpa, rewrite.bytes);
    defer again.deinit();
    const differs = try smfDifference(arena, sequence, &again.sequence);
    try p(w, "  (rung2 :ok {}", .{differs == null});
    if (differs) |why| {
        try pw(w, " :differs \"");
        if (!try renderText(w, why, rep)) return false;
        try pw(w, "\"");
    }
    if (!try renderDiags(w, "    ", &again.diags, rep)) return false;
    try pw(w, "))\n");
    return true;
}

/// `(write …)` over a `.mid`: the writer's output hashed, then read back
/// for the counts — a file nobody can read is not a file, and the
/// merge's event count is the point of the directive.
fn renderSmfWrite(
    gpa: Allocator,
    w: *Io.Writer,
    sequence: *const smf.Sequence,
    format0: bool,
    rep: Report,
) Error!bool {
    var written = try smf.write(gpa, sequence, .{ .format0 = format0 });
    defer written.deinit();
    var back = try smf.read(gpa, written.bytes);
    defer back.deinit();
    try p(w, "(write :format0 {} :sha256 \"", .{format0});
    try writeDigest(w, written.bytes);
    try p(w, "\" :bytes {d} :tracks {d} :events {d}", .{
        written.bytes.len,
        back.sequence.tracks.len,
        back.sequence.eventCount(),
    });
    if (!try renderDiags(w, "  ", &written.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// Null when two sequences hold the same events — rung 2's question.
/// Otherwise the first difference, named well enough to find it: the
/// golden carries the sentence, so a regression is a diff and not a
/// bisect.
///
/// Every event's `at`, kind and ACTIVE payload (an extern union's
/// inactive bytes are indeterminate — `eqlOutsidePool` is the one
/// comparison allowed), the pool bytes each payload names, and the
/// foreign chunks the reader preserved.
fn smfDifference(
    arena: Allocator,
    x: *const smf.Sequence,
    y: *const smf.Sequence,
) Error!?[]const u8 {
    if (x.format != y.format) return try std.fmt.allocPrint(
        arena,
        "format {d} became {d}",
        .{ x.format, y.format },
    );
    const x_ppq = x.division.pulsesPerQuarter();
    const y_ppq = y.division.pulsesPerQuarter();
    if (x_ppq != y_ppq) {
        return try std.fmt.allocPrint(arena, "the grid {d} became {d}", .{ x_ppq, y_ppq });
    }
    if (x.tracks.len != y.tracks.len) return try std.fmt.allocPrint(
        arena,
        "{d} tracks became {d}",
        .{ x.tracks.len, y.tracks.len },
    );

    for (x.tracks, y.tracks, 0..) |tx, ty, ti| {
        if (try smfTrackDifference(arena, x, y, ti, tx.events, ty.events)) |why| return why;
    }

    if (x.foreign.len != y.foreign.len) return try std.fmt.allocPrint(
        arena,
        "{d} foreign chunks became {d}",
        .{ x.foreign.len, y.foreign.len },
    );
    for (x.foreign, y.foreign, 0..) |fx, fy, i| {
        if (!std.mem.eql(u8, &fx.tag, &fy.tag))
            return try std.fmt.allocPrint(arena, "foreign chunk {d} changed tag", .{i});
        if (!std.mem.eql(u8, x.bytesOf(fx.bytes), y.bytesOf(fy.bytes)))
            return try std.fmt.allocPrint(arena, "foreign chunk {d} changed bytes", .{i});
    }
    return null;
}

/// Track `ti` of both sequences, event for event: the tick, the kind,
/// the active payload, and the pool bytes the payload names (read
/// against each event's own sequence). Null when all agree.
fn smfTrackDifference(
    arena: Allocator,
    x: *const smf.Sequence,
    y: *const smf.Sequence,
    ti: usize,
    x_events: []const smf.Event,
    y_events: []const smf.Event,
) Error!?[]const u8 {
    if (x_events.len != y_events.len) return try std.fmt.allocPrint(
        arena,
        "track {d}: {d} events became {d}",
        .{ ti, x_events.len, y_events.len },
    );
    for (x_events, y_events, 0..) |ex, ey, ei| {
        if (ex.at != ey.at) return try std.fmt.allocPrint(
            arena,
            "track {d} event {d}: tick {d} became {d}",
            .{ ti, ei, ex.at, ey.at },
        );
        if (ex.kind != ey.kind) return try std.fmt.allocPrint(
            arena,
            "track {d} event {d}: {s} became {s}",
            .{ ti, ei, @tagName(ex.kind), @tagName(ey.kind) },
        );
        if (!ex.payload.eqlOutsidePool(ey.payload, ex.kind)) return try std.fmt.allocPrint(
            arena,
            "track {d} event {d}: the {s} payload changed",
            .{ ti, ei, @tagName(ex.kind) },
        );
        const bx = ex.payload.poolBytes(ex.kind);
        const by = ey.payload.poolBytes(ey.kind);
        const pool_differs = bx != null and !std.mem.eql(u8, x.bytesOf(bx.?), y.bytesOf(by.?));
        if (pool_differs) return try std.fmt.allocPrint(
            arena,
            "track {d} event {d}: the {s} bytes changed",
            .{ ti, ei, @tagName(ex.kind) },
        );
    }
    return null;
}

// ---- the IT half ----

fn renderItCase(
    gpa: Allocator,
    arena: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    loaded: ?*Loaded,
    rep: Report,
) Error!bool {
    // The module's opaque regions point INTO these bytes: a `Module` is
    // meaningful only against the file it was read from, which is why
    // the anchor is handed to every writer below.
    var r = try itf.read.read(gpa, fixture.bytes);
    defer r.deinit();

    for (directives) |d| switch (d) {
        .read => if (!try renderItRead(w, &r, rep)) return false,
        .roundtrip => {
            if (!try renderItRoundtrip(gpa, arena, w, fixture.bytes, &r.module, rep)) return false;
        },
        .walk => |max_rows| {
            if (!try renderWalk(gpa, w, &r.module, max_rows, rep)) return false;
        },
        .write => |opts| {
            if (opts.format0) {
                // `:format0` is the SMF merge; an IT module has no
                // tracks to merge and the schema says so in the key's
                // own description.
                rep.say("(write :format0 true) is the SMF merge; this case's fixture is {s}\n", .{
                    fixture.file,
                });
                return false;
            }
            if (!try renderItWrite(gpa, w, &r.module, fixture.bytes, rep)) return false;
        },
        .unrun => |head| {
            rep.say("UNRUN {s} — the directive lands with a later part\n", .{head});
            return false;
        },
        else => {
            std.debug.assert(d.needsDocument());
            if (!try renderDocDirective(gpa, w, d, loaded.?, rep)) return false;
        },
    };
    return true;
}

/// `(read …)` over a `.it`: the header's facts and the module's counts,
/// and everything the reader complained of.
fn renderItRead(w: *Io.Writer, r: *const itf.read.Result, rep: Report) Error!bool {
    const m = &r.module;
    try pw(w, "(read\n  (it :title \"");
    if (!try renderText(w, itf.model.nameText(&m.header.title), rep)) return false;
    try p(w, "\" :speed {d} :tempo {d} :orders {d} :patterns {d} :instruments {d}" ++
        " :samples {d} :message-len {d} :tmpu {})", .{
        m.header.initial_speed,
        m.header.initial_tempo,
        m.orders.len,
        m.patterns.len,
        m.instruments.len,
        m.samples.len,
        m.message.len,
        m.tmpu != null,
    });
    if (!try renderDiags(w, "  ", &r.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// `(roundtrip …)` over a `.it`: rung 1 against the fixture's own bytes,
/// then rung 2 with every pass-through region compared against its own
/// anchor.
fn renderItRoundtrip(
    gpa: Allocator,
    arena: Allocator,
    w: *Io.Writer,
    bytes: []const u8,
    module: *const itf.Module,
    rep: Report,
) Error!bool {
    var rewrite = try itf.write.write(gpa, module, bytes, .{});
    defer rewrite.deinit();
    try p(w, "(roundtrip\n  (rung1 :ok {} :sha256 \"", .{std.mem.eql(u8, rewrite.bytes, bytes)});
    try writeDigest(w, rewrite.bytes);
    try pw(w, "\"");
    if (!try renderDiags(w, "    ", &rewrite.diags, rep)) return false;
    try pw(w, ")\n");

    var again = try itf.read.read(gpa, rewrite.bytes);
    defer again.deinit();
    const differs = try itDifference(arena, module, bytes, &again.module, rewrite.bytes);
    try p(w, "  (rung2 :ok {}", .{differs == null});
    if (differs) |why| {
        try pw(w, " :differs \"");
        if (!try renderText(w, why, rep)) return false;
        try pw(w, "\"");
    }
    if (!try renderDiags(w, "    ", &again.diags, rep)) return false;
    try pw(w, "))\n");
    return true;
}

/// `(write …)` over a `.it`: the writer's output hashed, then read back
/// for the module's own counts.
fn renderItWrite(
    gpa: Allocator,
    w: *Io.Writer,
    module: *const itf.Module,
    bytes: []const u8,
    rep: Report,
) Error!bool {
    var written = try itf.write.write(gpa, module, bytes, .{});
    defer written.deinit();
    var back = try itf.read.read(gpa, written.bytes);
    defer back.deinit();
    try pw(w, "(write :sha256 \"");
    try writeDigest(w, written.bytes);
    try p(w, "\" :bytes {d} :orders {d} :patterns {d} :samples {d}", .{
        written.bytes.len,
        back.module.orders.len,
        back.module.patterns.len,
        back.module.samples.len,
    });
    if (!try renderDiags(w, "  ", &written.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// The IT timing walk's `RowMap`, as text: every row PLAYED with its
/// start and length, the tempo segments, the note onsets, the total and
/// the loop point, then whatever the walk complained of.
///
/// Rows and onsets are capped: a runaway module plays a million rows,
/// and a golden nobody can read is not evidence. What was left out is
/// stated rather than dropped.
fn renderWalk(
    gpa: Allocator,
    w: *Io.Writer,
    module: *const itf.Module,
    max_rows: u32,
    rep: Report,
) Error!bool {
    var map = try itf.walk.derive(gpa, module, .{ .max_rows = max_rows });
    defer map.deinit();

    try p(w, "(walk :max-rows {d}", .{max_rows});
    for (map.rows[0..@min(map.rows.len, MAX_ROWS_ECHOED)]) |row| {
        try p(w, "\n  (row :order {d} :pattern {d} :row {d} :start {d} :ticks {d})", .{
            row.order, row.pattern, row.row, row.start_tick, row.ticks,
        });
    }
    if (map.rows.len > MAX_ROWS_ECHOED) try p(
        w,
        "\n  (rows-elided {d})",
        .{map.rows.len - MAX_ROWS_ECHOED},
    );

    for (map.segments) |seg| {
        try p(w, "\n  (segment :tick {d} :tempo {d})", .{ seg.start_tick, seg.tempo });
    }
    for (map.onsets[0..@min(map.onsets.len, MAX_ONSETS_ECHOED)]) |onset| {
        try p(
            w,
            "\n  (onset :ch {d} :tick {d} :note {d})",
            .{ onset.channel, onset.tick, onset.cell.note },
        );
    }
    if (map.onsets.len > MAX_ONSETS_ECHOED) try p(
        w,
        "\n  (onsets-elided {d})",
        .{map.onsets.len - MAX_ONSETS_ECHOED},
    );

    try p(w, "\n  (total :ticks {d} :loop-row ", .{map.total_ticks});
    if (map.loop_row) |loop| {
        try p(w, "{d})", .{loop});
    } else {
        // No loop point: the walk stopped for another reason — the
        // runaway cap, or a module with nothing to play.
        try pw(w, "none)");
    }
    if (!try renderDiags(w, "  ", &map.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// Null when two modules hold the same music — rung 2's question for
/// `.it`. Header fields, orders, patterns cell by cell, the message, and
/// every pass-through region compared as BYTES against its own anchor.
///
/// The edit-history block is deliberately not compared: the writer drops
/// it unless `preserve_history` asks for it (it 03), so its absence is
/// policy rather than loss.
fn itDifference(
    arena: Allocator,
    x: *const itf.Module,
    x_src: []const u8,
    y: *const itf.Module,
    y_src: []const u8,
) Error!?[]const u8 {
    if (try itHeaderDifference(arena, &x.header, &y.header)) |why| return why;
    if (!std.mem.eql(u8, x.orders, y.orders)) return try std.fmt.allocPrint(
        arena,
        "the order list changed ({d} entries against {d})",
        .{ x.orders.len, y.orders.len },
    );
    if (!std.mem.eql(u8, x.message, y.message))
        return try std.fmt.allocPrint(arena, "the song message changed", .{});
    if (try itPatternsDifference(arena, x, y)) |why| return why;

    const src: Anchors = .{ .x = x_src, .y = y_src };
    if (try itInstrumentsDifference(arena, x, y, src)) |why| return why;
    if (try itSamplesDifference(arena, x, y, src)) |why| return why;
    return itTrailerDifference(arena, x, y, src);
}

/// The two modules' anchors: the bytes each one's opaque regions are
/// offsets into.
const Anchors = struct { x: []const u8, y: []const u8 };

/// The header's title, its twelve scalar fields and its two channel
/// tables, in that order. Null when all agree.
fn itHeaderDifference(
    arena: Allocator,
    hx: *const itf.model.Header,
    hy: *const itf.model.Header,
) Error!?[]const u8 {
    if (!std.mem.eql(u8, &hx.title, &hy.title))
        return try std.fmt.allocPrint(arena, "the title changed", .{});
    const fields = [_]struct { name: []const u8, x: u32, y: u32 }{
        .{ .name = "highlight-minor", .x = hx.highlight_minor, .y = hy.highlight_minor },
        .{ .name = "highlight-major", .x = hx.highlight_major, .y = hy.highlight_major },
        .{ .name = "cwtv", .x = hx.cwtv, .y = hy.cwtv },
        .{ .name = "cmwt", .x = hx.cmwt, .y = hy.cmwt },
        .{ .name = "flags", .x = hx.flags, .y = hy.flags },
        .{ .name = "special", .x = hx.special, .y = hy.special },
        .{ .name = "global-volume", .x = hx.global_volume, .y = hy.global_volume },
        .{ .name = "mix-volume", .x = hx.mix_volume, .y = hy.mix_volume },
        .{ .name = "initial-speed", .x = hx.initial_speed, .y = hy.initial_speed },
        .{ .name = "initial-tempo", .x = hx.initial_tempo, .y = hy.initial_tempo },
        .{ .name = "pan-separation", .x = hx.pan_separation, .y = hy.pan_separation },
        .{ .name = "pitch-wheel-depth", .x = hx.pitch_wheel_depth, .y = hy.pitch_wheel_depth },
    };
    for (fields) |f| {
        if (f.x != f.y)
            return try std.fmt.allocPrint(arena, "{s} {d} became {d}", .{ f.name, f.x, f.y });
    }
    if (!std.mem.eql(u8, &hx.channel_pan, &hy.channel_pan))
        return try std.fmt.allocPrint(arena, "the channel pan table changed", .{});
    if (!std.mem.eql(u8, &hx.channel_vol, &hy.channel_vol))
        return try std.fmt.allocPrint(arena, "the channel volume table changed", .{});
    return null;
}

/// The patterns, row count then cell by cell. Null when all agree.
fn itPatternsDifference(
    arena: Allocator,
    x: *const itf.Module,
    y: *const itf.Module,
) Error!?[]const u8 {
    if (x.patterns.len != y.patterns.len) return try std.fmt.allocPrint(
        arena,
        "{d} patterns became {d}",
        .{ x.patterns.len, y.patterns.len },
    );
    for (x.patterns, y.patterns, 0..) |px, py, i| {
        if (px.rows != py.rows) return try std.fmt.allocPrint(
            arena,
            "pattern {d}: {d} rows became {d}",
            .{ i, px.rows, py.rows },
        );
        for (px.cells, py.cells, 0..) |cx, cy, at| {
            if (std.meta.eql(cx, cy)) continue;
            return try std.fmt.allocPrint(arena, "pattern {d} row {d} channel {d} changed", .{
                i,
                at / itf.model.channels,
                at % itf.model.channels,
            });
        }
    }
    return null;
}

/// The instruments: the count, then each one's name and raw bytes.
fn itInstrumentsDifference(
    arena: Allocator,
    x: *const itf.Module,
    y: *const itf.Module,
    src: Anchors,
) Error!?[]const u8 {
    if (x.instruments.len != y.instruments.len) return try std.fmt.allocPrint(
        arena,
        "{d} instruments became {d}",
        .{ x.instruments.len, y.instruments.len },
    );
    for (x.instruments, y.instruments, 0..) |ix, iy, i| {
        if (!std.mem.eql(u8, &ix.name, &iy.name))
            return try std.fmt.allocPrint(arena, "instrument {d} changed name", .{i});
        if (try regionDiffers(arena, "instrument", i, ix.raw, iy.raw, src)) |why| return why;
    }
    return null;
}

/// The samples: the count, then each one's name, descriptor, header
/// bytes and data bytes.
fn itSamplesDifference(
    arena: Allocator,
    x: *const itf.Module,
    y: *const itf.Module,
    src: Anchors,
) Error!?[]const u8 {
    if (x.samples.len != y.samples.len) return try std.fmt.allocPrint(
        arena,
        "{d} samples became {d}",
        .{ x.samples.len, y.samples.len },
    );
    for (x.samples, y.samples, 0..) |sx, sy, i| {
        if (!std.mem.eql(u8, &sx.name, &sy.name))
            return try std.fmt.allocPrint(arena, "sample {d} changed name", .{i});
        const same_shape = sx.bits == sy.bits and sx.channels == sy.channels and sx.enc == sy.enc;
        if (!same_shape) return try std.fmt.allocPrint(
            arena,
            "sample {d}'s descriptor changed ({d}-bit {s} became {d}-bit {s})",
            .{ i, sx.bits, @tagName(sx.enc), sy.bits, @tagName(sy.enc) },
        );
        if (try regionDiffers(arena, "sample header", i, sx.raw, sy.raw, src)) |why| return why;
        if (try regionDiffers(arena, "sample data", i, sx.data, sy.data, src)) |why| return why;
    }
    return null;
}

/// What follows the samples: the foreign chunks, the embedded MIDI
/// configuration and the `TMPU` payload, each by its own bytes.
fn itTrailerDifference(
    arena: Allocator,
    x: *const itf.Module,
    y: *const itf.Module,
    src: Anchors,
) Error!?[]const u8 {
    if (x.foreign.len != y.foreign.len) return try std.fmt.allocPrint(
        arena,
        "{d} foreign chunks became {d}",
        .{ x.foreign.len, y.foreign.len },
    );
    for (x.foreign, y.foreign, 0..) |fx, fy, i| {
        if (!std.mem.eql(u8, &fx.tag, &fy.tag))
            return try std.fmt.allocPrint(arena, "foreign chunk {d} changed tag", .{i});
        if (try regionDiffers(arena, "foreign chunk", i, fx.raw, fy.raw, src)) |why| return why;
    }

    if ((x.midi_config == null) != (y.midi_config == null))
        return try std.fmt.allocPrint(arena, "the MIDI configuration appeared or vanished", .{});
    if (x.midi_config) |mx| {
        const my = y.midi_config.?;
        if (try regionDiffers(arena, "MIDI configuration", 0, mx, my, src)) |why| return why;
    }
    if ((x.tmpu == null) != (y.tmpu == null))
        return try std.fmt.allocPrint(arena, "the TMPU chunk appeared or vanished", .{});
    if (x.tmpu) |tx| {
        if (try regionDiffers(arena, "TMPU payload", 0, tx, y.tmpu.?, src)) |why| return why;
    }
    return null;
}

/// Two opaque regions, each read against its OWN anchor: pass-through
/// means the bytes come back, not that the offsets do.
fn regionDiffers(
    arena: Allocator,
    comptime what: []const u8,
    index: usize,
    rx: itf.Region,
    ry: itf.Region,
    src: Anchors,
) Error!?[]const u8 {
    const bx = rx.slice(src.x);
    const by = ry.slice(src.y);
    if (bx == null or by == null) return try std.fmt.allocPrint(
        arena,
        what ++ " {d} left its anchor's bytes",
        .{index},
    );
    if (!std.mem.eql(u8, bx.?, by.?)) return try std.fmt.allocPrint(
        arena,
        what ++ " {d} changed bytes ({d} against {d})",
        .{ index, bx.?.len, by.?.len },
    );
    return null;
}

// ---------------------------------------------------------------------------
// The document half — P107's other side
// ---------------------------------------------------------------------------

/// What a case needs from the run to reach its own directory and the
/// timeline vocabulary. Both are constants of the WALK, not of the case,
/// so they ride in one value rather than four parameters.
const Env = struct {
    io: Io,
    /// The preloaded timeline bundle — the four composed manifests every
    /// `doc.sjon` is validated against. Preloaded ONCE for the whole
    /// walk, as the harness bundle is, and never composed with it.
    schema: *const Schema,
    /// The corpus directory and the case's name inside it: an anchor's
    /// `:file` is "resolved relative to the document" (plan 02), and the
    /// document lives here.
    root: []const u8,
    name: []const u8,
};

/// The case's document, derived, with everything it borrows from.
///
/// The fields are torn down in reverse: `store` owns the bytes an IT
/// tier's `(bin …)` regions point into, so it outlives the module that
/// names them.
const Loaded = struct {
    /// The anchor resolver's store, rooted at the case's directory.
    store: FsStore,
    /// A `doc.sjon` case: the document as the author wrote it.
    result: ?doc.Result,
    /// A `song.mid` / `song.it` case: the file DUMPED, through the very
    /// pipeline `tempura dump` runs — plan 04's five rules and all. That
    /// is what lets a residue case be a corpus case at all: the timeline
    /// tier a fixture gets is the one reconciliation produced for it, and
    /// the verdicts that produced it ride here beside the document.
    dumped: ?doc.pipeline.Dumped,
    derived: time.derive.Derived,
    /// The bytes an IT tier's opaque regions are offsets into, when this
    /// host could produce them. Null for every other document.
    it_source: ?[]const u8,
    /// The document's own SOURCE — `doc.sjon` itself, or the text the
    /// dump produced. `build` packs the essence out of it, so it is the
    /// text and not a re-print (plan 04).
    source: [:0]const u8,
    /// The timeline bundle, for the `build` and `dump` a `(build …)`
    /// over a native document runs.
    schema: *const Schema,

    fn deinit(self: *Loaded) void {
        self.derived.deinit();
        if (self.result) |*r| r.deinit();
        if (self.dumped) |*d| d.deinit();
        self.store.deinit();
        self.* = undefined;
    }

    /// The document, whichever of the two produced it.
    fn doc_(self: *Loaded) *doc.Doc {
        if (self.result) |*r| return &r.doc;
        return &self.dumped.?.doc;
    }

    /// What LOADING it had to say — the walk's diagnostics for a
    /// `doc.sjon`, and the read's, the carrier's, the reconciliation's
    /// and the re-load's for a file.
    fn loadDiags(self: *const Loaded) *const Diag.List {
        if (self.result) |*r| return &r.diags;
        return &self.dumped.?.diags;
    }

    /// The map the document layer derived — the one the printer spells
    /// positions with.
    fn map(self: *const Loaded) *const time.TimeMap.TimeMap {
        if (self.result) |*r| return &r.map;
        return &self.dumped.?.map;
    }
};

/// Load the case's document and derive it. Null = the case is void
/// (already reported).
///
/// Two inputs, one document. A `doc.sjon` IS one, read through
/// `doc/fromSjon.zig` with a resolver rooted at the case's directory (an
/// anchor's `:file` is resolved relative to the document, plan 02). A
/// `song.mid` or a `song.it` goes through `doc/pipeline.zig`'s `dump` —
/// the same function `tempura dump` runs, plan 04's five reconciliation
/// rules and all — so the timeline tier a fixture gets is the one the
/// file's own residue produced, or the skeleton plan 04's rule 1 derives
/// when there is none.
///
/// That is the whole reason the residue cases can be corpus cases: the
/// rule that ran, the verdict per lane and the verdict on the conductor
/// are facts about the fixture, and they land in the golden beside the
/// tier they produced.
fn loadDocument(
    gpa: Allocator,
    arena: Allocator,
    env: Env,
    fixture: Fixture,
) Error!?Loaded {
    const case_dir = try std.fs.path.join(arena, &.{ env.root, env.name });
    var store: FsStore = .init(gpa, env.io, case_dir);
    errdefer store.deinit();

    var result: ?doc.Result = null;
    errdefer if (result) |*r| r.deinit();
    var dumped: ?doc.pipeline.Dumped = null;
    errdefer if (dumped) |*d| d.deinit();

    switch (fixture.kind) {
        .doc => result = try doc.fromSource(gpa, env.schema, fixture.bytes, store.resolver()),
        .smf, .it => dumped = try doc.pipeline.dump(
            gpa,
            env.schema,
            fixture.bytes,
            if (fixture.kind == .smf) .smf else .it,
            .{ .file = fixture.file },
        ),
    }

    const document: *doc.Doc = if (result) |*r| &r.doc else &dumped.?.doc;
    const source: [:0]const u8 = if (result != null) fixture.bytes else dumped.?.text;

    const it_source: ?[]const u8 = switch (fixture.kind) {
        .it => fixture.bytes,
        else => blk: {
            // A `doc.sjon` with an inline IT dump: its `(bin …)` regions
            // are offsets into the anchor's file, so the store is asked
            // for exactly the file the anchor names.
            for (document.it) |tier| {
                const anchor = document.anchorById(tier.anchor) orelse continue;
                if (store.resolver().read(anchor.file)) |bytes| break :blk bytes;
            }
            break :blk null;
        },
    };

    const derived = try time.derive.derive(gpa, document);
    return .{
        .store = store,
        .result = result,
        .dumped = dumped,
        .derived = derived,
        .it_source = it_source,
        .source = source,
        .schema = env.schema,
    };
}

/// The derivation's own canonical text, once, at the top of the case:
/// the tempo segments with their exact bit patterns, the meters, the bar
/// table, the length, the sections, the cues and the lanes — then
/// everything the load and the derivation complained of.
///
/// This is the header the three `tempo-three-conductors*` cases must
/// agree on byte for byte (plan 03, phase 3).
fn renderEcho(arena: Allocator, w: *Io.Writer, loaded: *const Loaded, rep: Report) Error!bool {
    var buf: Io.Writer.Allocating = .init(arena);
    loaded.derived.echo(&buf.writer) catch return error.OutOfMemory;

    try pw(w, "(echo");
    var lines = std.mem.splitScalar(u8, buf.written(), '\n');
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        try p(w, "\n  {s}", .{line});
    }
    // The document's report and the derivation's, in that order: a
    // document that does not load is still a case, and the golden says
    // why rather than the case simply vanishing.
    if (!try renderDiags(w, "  ", loaded.loadDiags(), rep)) return false;
    if (!try renderDiags(w, "  ", &loaded.derived.diags, rep)) return false;
    try pw(w, ")\n");
    return try renderReconciled(w, loaded);
}

/// What plan 04's reconciliation made of a FILE fixture: which of the
/// five rules produced the timeline tier, what the conductor record said
/// and what each lane record said.
///
/// Nothing for a `doc.sjon` case, which has no carrier and no verdicts —
/// the three `tempo-three-conductors*` cases are documents, so this line
/// never disturbs the echo they agree on.
///
/// The rule NAME and the verdicts are the whole content of a residue
/// case: `(reconciled :rule restored)` with every hash matching is a file
/// nobody has touched, and `:action bound` beside `:hash-ok false` is the
/// DAW's edit winning over a stale essence, which is the sentence plan 04
/// exists to make true.
fn renderReconciled(w: *Io.Writer, loaded: *const Loaded) Error!bool {
    const d = if (loaded.dumped) |*x| x else return true;
    try p(w, "(reconciled :rule {t}", .{d.rule});
    if (d.conductor) |c| try p(w, " :conductor-hash-ok {} :file-conducts {}", .{
        c.hash_ok,
        c.file_conducts,
    }) else try pw(w, " :conductor none");
    for (d.verdicts) |v| {
        try p(
            w,
            "\n  (verdict :lane {s} :hash-ok {} :action {t})",
            .{ v.lane, v.hash_ok, v.action },
        );
        for (v.hints) |h| try p(
            w,
            "\n    (hint :from {d} :to {d} :ease {s})",
            .{ h.from, h.to, h.ease },
        );
    }
    // Rule 2's consumption, when it took anything: the restored lanes'
    // view and the conductor's, out of the file tier (plan 04, "One
    // home"). Pinned here because the fact it makes true — a rebuild of
    // the dump renders each lane once — is a property of the DUMP.
    if (d.consumed.any()) try p(w, "\n  (consumed :events {d} :cells {d} :conductor {d})", .{
        d.consumed.events,
        d.consumed.cells,
        d.consumed.conductor,
    });
    try pw(w, ")\n");
    return true;
}

/// One directive of the document half. False = a defect that voids the
/// golden.
///
/// The switch is EXHAUSTIVE and its two halves are `needsDocument`'s two
/// halves: a directive added to one without the other stops compiling
/// here, which is what keeps every caller's "a document was loaded
/// because this needed one" sound.
fn renderDocDirective(
    gpa: Allocator,
    w: *Io.Writer,
    d: Directive,
    loaded: *Loaded,
    rep: Report,
) Error!bool {
    std.debug.assert(d.needsDocument());
    switch (d) {
        .times => |seconds| try renderTimes(gpa, w, seconds, loaded),
        .at => |tick| {
            var pos = try Playhead.atTick(gpa, &loaded.derived, tick);
            defer pos.deinit(gpa);
            try renderPosition(w, pos, null);
        },
        .snap => |ask| {
            try p(w, "(snapped :tick {d})\n", .{
                Playhead.snap(&loaded.derived, ask.tick, ask.grid, ask.swing),
            });
        },
        .dump => if (!try renderTierDump(gpa, w, loaded, rep)) return false,
        .build => |ask| {
            if (!try renderBuild(gpa, w, ask, loaded, rep)) return false;
        },
        .plan => |op_json| {
            if (!try renderPlan(gpa, w, op_json, loaded, rep)) return false;
        },
        .export_score => |ask| {
            if (!try renderScore(gpa, w, ask, loaded, rep)) return false;
        },
        // Everything `needsDocument` answers false for; the assertion
        // above is what makes this arm unreachable rather than a silent
        // no-op.
        .read, .roundtrip, .walk, .write, .unrun => unreachable,
    }
    return true;
}

/// `times`: where each second falls. `Playhead.at` takes seconds from
/// OUTSIDE, so the two host guards ride out with it: a case may ask about
/// an infinity, and the golden says which guard answered.
fn renderTimes(gpa: Allocator, w: *Io.Writer, seconds: []const f64, loaded: *Loaded) Error!void {
    for (seconds) |secs| {
        var pos = Playhead.at(gpa, &loaded.derived, secs) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => {
                try p(w, "(at :seconds \"{X:0>16}\" :refused {s})\n", .{
                    @as(u64, @bitCast(secs)),
                    refusalName(err),
                });
                continue;
            },
        };
        defer pos.deinit(gpa);
        try renderPosition(w, pos, secs);
    }
}

/// `dump`: the TIMELINE tier alone — the roots that are not `midi/` or
/// `it/` forms. A file tier is the file dumped whole, and a golden that
/// carried it would be a second copy of bytes the `(fixture …)` line
/// already pins; what this verb is for is the timeline a read-write
/// round trip produces. False = a defect that voids the golden.
fn renderTierDump(gpa: Allocator, w: *Io.Writer, loaded: *Loaded, rep: Report) Error!bool {
    // A shallow copy with the two tiers emptied, printed by the real
    // printer, rather than a line filter over its output: the grouping
    // (which blank line separates what) is the printer's rule and stays
    // its own. The copy is never deinitialised — the arena it names is
    // still the original's.
    var tier_free = loaded.doc_().*;
    tier_free.midi = &.{};
    tier_free.it = &.{};
    const text = try doc.print(gpa, &tier_free, loaded.map(), .{});
    defer gpa.free(text);
    try p(w, "(dump :bytes {d} :sha256 \"", .{text.len});
    try writeDigest(w, text);
    try pw(w, "\")\n");
    // The tier itself, one line per line behind a `;| ` marker: the text
    // is what a reviewer reads, and a comment prefix is what keeps a
    // golden one SJON document rather than two.
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line| {
        if (line.len == 0 and lines.peek() == null) break;
        if (line.len == 0) {
            try pw(w, ";|\n");
            continue;
        }
        if (!try renderRawLine(w, line, rep)) return false;
    }
    return true;
}

/// One line of a dumped tier. A control byte is refused for the reason a
/// diagnostic's is: a golden nobody can read is not evidence.
fn renderRawLine(w: *Io.Writer, line: []const u8, rep: Report) Error!bool {
    try pw(w, ";| ");
    for (line) |b| {
        if (b < 0x20) {
            rep.say("control byte in a dumped line — not renderable\n", .{});
            return false;
        }
    }
    try pw(w, line);
    try pw(w, "\n");
    return true;
}

/// One position, as the golden spells it. `:seconds` is present exactly
/// when the question was asked in seconds, which is what tells the two
/// queries apart in a golden read on its own.
fn renderPosition(w: *Io.Writer, pos: Playhead.Position, seconds: ?f64) Error!void {
    try pw(w, "(at");
    if (seconds) |secs| try p(w, " :seconds \"{X:0>16}\"", .{@as(u64, @bitCast(secs))});
    try p(w, " :tick {d} :bar {d} :beat {d} :sub {d} :into-bar \"{X:0>16}\" :sections [", .{
        pos.tick,
        pos.bar,
        pos.beat,
        pos.sub_ticks,
        @as(u64, @bitCast(pos.seconds_into_bar)),
    });
    for (pos.section_ids, 0..) |id, i| {
        if (i > 0) try pw(w, " ");
        try p(w, "{d}", .{id});
    }
    try pw(w, "] :prev-cue ");
    try renderOptIndex(w, pos.prev_cue);
    try pw(w, " :next-cue ");
    try renderOptIndex(w, pos.next_cue);
    // The tracker position, for a document an IT anchor conducts (plan
    // 03: the studio shows it with no renderer readback).
    if (pos.order_row) |orow| try p(w, " :order {d} :row {d} :tick-in-row {d}", .{
        orow.order,
        orow.row,
        orow.tick_in_row,
    });
    try pw(w, ")\n");
}

/// The name a golden spells a host guard with. Kebab-case, like every
/// other symbol a golden carries and like the `Diag.Code` each of these
/// becomes at the layer above (`tick_overflow`) — the golden is not Zig,
/// and a reader should not have to translate a CamelCase error name.
fn refusalName(err: Playhead.Error) []const u8 {
    return switch (err) {
        error.TickOverflow => "tick-overflow",
        error.NonFiniteTime => "non-finite-time",
        error.OutOfMemory => unreachable,
    };
}

fn renderOptIndex(w: *Io.Writer, index: ?u32) Error!void {
    if (index) |i| try p(w, "{d}", .{i}) else try pw(w, "none");
}

/// One edit operation, planned and applied — plan 07's contract as a
/// golden.
///
/// Both halves are pinned because both are the contract: the ACTIONS are
/// what a host sends to SJON and what `edit --dry-run` prints, and the
/// APPLIED DOCUMENT is what comes back with `layout = .preserve`, which
/// is the claim a diff can actually check ("trivia outside the touched
/// sub-trees survives"). A plan whose actions were right and whose
/// splice was not would pass on the first half alone.
///
/// A refusal is an outcome, not a defect: `(planned :refused true)` with
/// its diagnostic is exactly what plan 07 promises for an operation that
/// cannot be done, and several cases exist for it.
fn renderPlan(
    gpa: Allocator,
    w: *Io.Writer,
    op_json: []const u8,
    loaded: *Loaded,
    rep: Report,
) Error!bool {
    var parsed = try edit_engine.fromJson(gpa, op_json);
    defer parsed.deinit();

    const op = parsed.op orelse {
        try pw(w, "(planned :read false");
        if (!try renderDiags(w, "  ", &parsed.diags, rep)) return false;
        try pw(w, ")\n");
        return true;
    };

    var tree = try sjon.parse(gpa, loaded.source);
    defer tree.deinit();

    var plan = try edit_engine.planWith(gpa, loaded.doc_(), &tree, loaded.map(), op);
    defer plan.deinit();

    const sum = plan.summary;
    try p(
        w,
        "(planned :targets {d} :set {d} :inserted {d} :removed {d} :replaced {d} :inexact {d} " ++
            ":refused {}",
        .{
            sum.targets,
            sum.set,
            sum.inserted,
            sum.removed,
            sum.replaced,
            sum.inexact,
            sum.refused,
        },
    );
    if (!try renderDiags(w, "  ", &plan.diags, rep)) return false;
    try pw(w, ")\n");

    const actions = try plan.text(gpa);
    defer gpa.free(actions);
    if (!try renderRaw(w, actions, rep)) return false;

    var applied = try edit_engine.apply(gpa, loaded.source, &plan);
    defer applied.deinit();
    try p(w, "(applied :bytes {d} :sha256 \"", .{applied.text.len});
    try writeDigest(w, applied.text);
    try pw(w, "\"");
    if (!try renderDiags(w, "  ", &applied.diags, rep)) return false;
    try pw(w, ")\n");
    return renderRaw(w, applied.text, rep);
}

/// The document as a pacer score — plan 08's `exportScore`, hashed and
/// with its first lines shown.
///
/// The hash is the determinism claim (the same document gives the same
/// score on every host) and the lines are what makes a diff readable:
/// the header comment counts the roundings and the aggregations, and the
/// transport is the first form, so the first dozen lines are where a
/// change in the conversion actually shows.
///
/// The EASING HINTS come from the reconciliation when the fixture is a
/// file: plan 04's rule 2 keeps a stale curve lane's easing "verified
/// against the steps and dropped where it disagrees", and this is the
/// one place both halves — the verdict and the score it shapes — are
/// pinned together.
fn renderScore(
    gpa: Allocator,
    w: *Io.Writer,
    ask: ScoreAsk,
    loaded: *Loaded,
    rep: Report,
) Error!bool {
    var hints: std.ArrayList(exporter.score.EaseHint) = .empty;
    defer hints.deinit(gpa);
    if (loaded.dumped) |*d| {
        for (d.verdicts) |v| {
            for (v.hints) |h| try hints.append(gpa, .{
                .lane = v.lane,
                .from = h.from,
                .to = h.to,
                .ease = h.ease,
            });
        }
    }

    var res = try exporter.exportScore(gpa, loaded.doc_(), &loaded.derived, hints.items, .{
        .max_keys_per_track = ask.max_keys,
    });
    defer res.deinit();

    try p(w, "(score :bytes {d} :sha256 \"", .{res.text.len});
    try writeDigest(w, res.text);
    try p(w, "\" :meter [{d} {d}] :seconds-mode {} :aggregated {d} :hints {d}", .{
        res.meter[0],
        res.meter[1],
        res.seconds_mode,
        res.aggregated,
        hints.items.len,
    });
    if (!try renderDiags(w, "  ", &res.diags, rep)) return false;
    try pw(w, ")\n");

    var it = std.mem.splitScalar(u8, res.text, '\n');
    var n: u32 = 0;
    while (it.next()) |line| : (n += 1) {
        if (n >= ask.lines) break;
        if (line.len == 0 and it.peek() == null) break;
        if (line.len == 0) {
            try pw(w, ";|\n");
            continue;
        }
        if (!try renderRawLine(w, line, rep)) return false;
    }
    return true;
}

/// A whole text behind the `;| ` marker, one line at a time — what keeps
/// a golden ONE SJON document while still showing a person the bytes.
fn renderRaw(w: *Io.Writer, text: []const u8, rep: Report) Error!bool {
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line| {
        if (line.len == 0 and lines.peek() == null) break;
        if (line.len == 0) {
            try pw(w, ";|\n");
            continue;
        }
        if (!try renderRawLine(w, line, rep)) return false;
    }
    return true;
}

/// The document as a file, and rung 1 over what came out.
///
/// Two paths, one verb. An ANCHORED document is its inline tier through
/// the canonical writer — the document and the file said twice, which is
/// what those cases are about, and the residue is not written over bytes
/// a fixture pins. A NATIVE document has no tier, so it goes through
/// `doc/pipeline.zig`'s `build`: plan 08's renderers, plan 04's carriers
/// and the canonical writer, with rung 3 — the dump of what was just
/// built, against the document that built it — beside rung 1.
fn renderBuild(
    gpa: Allocator,
    w: *Io.Writer,
    ask: BuildAsk,
    loaded: *Loaded,
    rep: Report,
) Error!bool {
    const d = loaded.doc_();
    switch (ask.kind) {
        .mid => {
            if (d.midi.len == 0) return try renderRendered(gpa, w, ask, loaded, .smf, rep);
            var written = try smf.write(gpa, &d.midi[0].sequence, .{});
            defer written.deinit();
            var back = try smf.read(gpa, written.bytes);
            defer back.deinit();
            var again = try smf.write(gpa, &back.sequence, .{});
            defer again.deinit();
            return try renderBuilt(
                w,
                ask.kind,
                written.bytes,
                std.mem.eql(u8, again.bytes, written.bytes),
                &written.diags,
                rep,
            );
        },
        .it => {
            if (d.it.len == 0) return try renderRendered(gpa, w, ask, loaded, .it, rep);
            var written = try itf.write.write(gpa, &d.it[0].module, loaded.it_source, .{});
            defer written.deinit();
            var back = try itf.read.read(gpa, written.bytes);
            defer back.deinit();
            var again = try itf.write.write(gpa, &back.module, written.bytes, .{});
            defer again.deinit();
            return try renderBuilt(
                w,
                ask.kind,
                written.bytes,
                std.mem.eql(u8, again.bytes, written.bytes),
                &written.diags,
                rep,
            );
        },
    }
}

/// A native timeline rendered into a file — plan 08 phase 5's whole
/// chain, as the CLI's `build` verb runs it.
///
/// Four facts go in the golden: the bytes (length and hash — the
/// determinism claim, the same on every host), what the residue cost,
/// rung 1 over the bytes, and rung 3: the dump of what was just built,
/// compared with the document that built it. Rung 3 is plan 09's
/// essence-exactness gate, and a golden can say it in one flag because
/// `Doc.eql` compares the two documents form for form with the FILE
/// tiers lifted off — the anchor and the dump a build had to invent are
/// the file's half, and the timeline tier is the half that has to come
/// back.
fn renderRendered(
    gpa: Allocator,
    w: *Io.Writer,
    ask: BuildAsk,
    loaded: *Loaded,
    kind: doc.AnchorKind,
    rep: Report,
) Error!bool {
    var built = try doc.pipeline.build(
        gpa,
        loaded.schema,
        loaded.source,
        loaded.doc_(),
        &loaded.derived,
        kind,
        .{ .cc = ask.cc },
    );
    defer built.deinit();

    if (built.bytes.len == 0) {
        try p(w, "(built :kind {s} :refused true", .{@tagName(ask.kind)});
        if (!try renderDiags(w, "  ", &built.diags, rep)) return false;
        try pw(w, ")\n");
        return true;
    }

    try p(w, "(built :kind {s} :len {d} :sha256 \"", .{ @tagName(ask.kind), built.bytes.len });
    try writeDigest(w, built.bytes);
    try p(w, "\"\n  (rung1 :ok {})\n  (residue :essence {d} :lanes {d} :conductor {})\n  (rung3 " ++
        ":ok {})", .{
        try rung1Of(gpa, kind, built.bytes),
        built.essence_bytes,
        built.lanes.len,
        built.conductor != null,
        try rung3Of(gpa, loaded, kind, built.bytes),
    });
    if (!try renderDiags(w, "  ", &built.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// `write(read(bytes)) == bytes` over what a build produced.
fn rung1Of(gpa: Allocator, kind: doc.AnchorKind, bytes: []const u8) Error!bool {
    switch (kind) {
        .smf => {
            var back = try smf.read(gpa, bytes);
            defer back.deinit();
            var again = try smf.write(gpa, &back.sequence, .{});
            defer again.deinit();
            return std.mem.eql(u8, again.bytes, bytes);
        },
        .it => {
            var back = try itf.read.read(gpa, bytes);
            defer back.deinit();
            var again = try itf.write.write(gpa, &back.module, bytes, .{});
            defer again.deinit();
            return std.mem.eql(u8, again.bytes, bytes);
        },
    }
}

/// `dump(build(doc))` against `doc`, timeline tier for timeline tier.
///
/// The file's half is lifted off BOTH sides. The anchor and the dump a
/// build had to invent are the file's, and so is the anchor the AUTHOR
/// wrote: a native document arranged around `impulse-04.it` names one
/// file before the build and another after it, and comparing one
/// document's anchors against the other's empty list made the rung false
/// for every anchored document at once — `corpus/examples-native` was the
/// one case that had an anchor, and it reported a loss that had not
/// happened (the final review's D1, second half). What rung 3 claims is
/// plan 09's essence-exactness: the TIMELINE tier comes back.
fn rung3Of(gpa: Allocator, loaded: *Loaded, kind: doc.AnchorKind, bytes: []const u8) Error!bool {
    var dumped = try doc.pipeline.dump(gpa, loaded.schema, bytes, kind, .{});
    defer dumped.deinit();
    if (dumped.diags.hasErrors()) return false;
    // Shallow copies with the FILE tiers emptied — never deinitialised,
    // because the arenas they name are still the two documents'.
    var tier_free = dumped.doc;
    tier_free.anchors = &.{};
    tier_free.midi = &.{};
    tier_free.it = &.{};
    var want = loaded.doc_().*;
    want.anchors = &.{};
    want.midi = &.{};
    want.it = &.{};
    return tier_free.eql(&want);
}

fn renderBuilt(
    w: *Io.Writer,
    kind: BuildKind,
    bytes: []const u8,
    rung1: bool,
    diags: *const Diag.List,
    rep: Report,
) Error!bool {
    try p(w, "(built :kind {s} :len {d} :sha256 \"", .{ @tagName(kind), bytes.len });
    try writeDigest(w, bytes);
    try p(w, "\"\n  (rung1 :ok {})", .{rung1});
    if (!try renderDiags(w, "  ", diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

// ---------------------------------------------------------------------------
// Reporting
// ---------------------------------------------------------------------------

/// The first line at which two goldens part, expected against actual.
const Mismatch = struct {
    line: usize,
    expected: ?[]const u8,
    actual: ?[]const u8,
};

/// Null when the two texts are byte-equal. Otherwise the first line that
/// differs, with `null` on the side that ended first — enough to see a
/// changed hash or a missing row without dumping whole files.
///
/// The walk always finds that line: splitting on `\n` is injective, so
/// two texts with the same sequence of lines are the same text, and the
/// equality above already returned for those. A golden that differs only
/// in its final newline differs at the line AFTER the shorter one's last
/// (`null` against `""`), which the test below pins.
fn firstDifference(expected: []const u8, actual: []const u8) ?Mismatch {
    if (std.mem.eql(u8, expected, actual)) return null;
    var exp_lines = std.mem.splitScalar(u8, expected, '\n');
    var act_lines = std.mem.splitScalar(u8, actual, '\n');
    var line: usize = 1;
    while (true) : (line += 1) {
        const e = exp_lines.next();
        const ac = act_lines.next();
        // Both exhausted would mean line-identical texts, which the
        // byte equality above ruled out — an internal invariant, not a
        // condition of the input.
        std.debug.assert(e != null or ac != null);
        if (e != null and ac != null and std.mem.eql(u8, e.?, ac.?)) continue;
        return .{ .line = line, .expected = e, .actual = ac };
    }
}

fn reportMismatch(out: *Io.Writer, name: []const u8, diff: Mismatch) !void {
    try out.print("corpus: {s}: MISMATCH at line {d}\n  expected: {s}\n  actual:   {s}\n", .{
        name,
        diff.line,
        diff.expected orelse "<end of file>",
        diff.actual orelse "<end of file>",
    });
    try out.print(
        "corpus: {s}: `zig build corpus -- --update` regenerates (review the diff)\n",
        .{name},
    );
}

// ---------------------------------------------------------------------------
// Tests — the harness vocabulary, the renderer and the verdict.
// Discovered through `root.zig`'s test block.
// ---------------------------------------------------------------------------

const t_ = std.testing;

/// One harness source through the real reader, with the report captured.
/// `.directives` is null exactly when the runner would fail the case;
/// `.report` is what it printed — which is how the tests below pin WHICH
/// layer refused, the schema or the runner.
const ParseProbe = struct { directives: ?[]const Directive, report: []const u8 };

fn testParse(arena: Allocator, src: [:0]const u8) !ParseProbe {
    var hs = try Schema.loadCorpus(t_.allocator);
    defer hs.deinit();
    var sink: Io.Writer.Allocating = .init(arena);
    const d = try parseHarness(arena, t_.allocator, &hs, &sink.writer, "test", src);
    return .{ .directives = d, .report = sink.written() };
}

/// The first line of a schema report — `parseHarness` prints it before
/// the per-diagnostic lines and nothing else does.
const SCHEMA_REFUSED = "does not validate";

test "corpus harness: the embedded manifest preloads clean and declares every directive" {
    var hs = try Schema.loadCorpus(t_.allocator);
    defer hs.deinit();

    try t_.expectEqual(@as(usize, 0), hs.preloaded.diagnostics.len);
    try t_.expectEqual(@as(usize, 1), hs.preloaded.plugins.len);
    try t_.expectEqualStrings("tempura-corpus", hs.preloaded.plugins[0].name);
    for ([_][]const u8{
        "read",  "roundtrip", "walk",  "write",        "at",
        "snap",  "plan",      "build", "export-score", "dump",
        "times",
    }) |head| {
        try t_.expect(hs.preloaded.schema.lookupForm(head, null) == .found);
    }
    // …and `timing` is not one of them any more: the verb it declared
    // had no implementation and never would (pstudio is not a host), so
    // a case that asked for it validated and then failed as `UNRUN`.
    try t_.expect(hs.preloaded.schema.lookupForm("timing", null) != .found);
}

test "corpus harness: a well-formed file reads through the schema, defaults and all" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const d = (try testParse(arena,
        \\(read)
        \\(roundtrip)
        \\(walk)
        \\(walk :max-rows 3)
        \\(write)
        \\(write :format0 true)
    )).directives.?;

    try t_.expectEqual(@as(usize, 6), d.len);
    try t_.expectEqual(Directive.read, d[0]);
    try t_.expectEqual(Directive.roundtrip, d[1]);
    // `:max-rows` omitted is the MANIFEST's default, read back through
    // `EffectiveView` — one spelling per default, and it is the walk's
    // own ceiling.
    try t_.expectEqual(@as(u32, 1 << 20), d[2].walk);
    try t_.expectEqual(@as(u32, 3), d[3].walk);
    try t_.expectEqual(false, d[4].write.format0);
    try t_.expectEqual(true, d[5].write.format0);
}

test "corpus harness: the schema refuses what the runner would otherwise hand-check" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Each of these is an SJON diagnostic carrying a span, pinned by
    // CODE — so a runner check quietly taking the refusal back would
    // fail here.
    const cases = [_]struct { src: [:0]const u8, code: []const u8 }{
        .{ .src = "(walk :max-rows 0)", .code = "number_below_min" },
        .{ .src = "(walk :max-rows 1048577)", .code = "number_above_max" },
        .{ .src = "(walk :max-rows 1.5)", .code = "number_not_integer" },
        .{ .src = "(walk :max-rows 3b)", .code = "unit_forbidden" },
        .{ .src = "(write :format0 1)", .code = "wrong_underlying" },
        .{ .src = "(read :bogus 1)", .code = "unknown_key" },
        .{ .src = "(rewind :to 0)", .code = "unknown_form" },
    };
    for (cases) |c| {
        const probe = try testParse(arena, c.src);
        try t_.expect(probe.directives == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) != null);
        try t_.expect(std.mem.indexOf(u8, probe.report, c.code) != null);
    }
}

test "corpus harness: what a schema cannot see stays the runner's" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // A bare value at the root is governed by no `(form …)` declaration,
    // and "at least one directive" is a document-level fact. Neither is
    // a shape a form-at-a-time schema sees, so both refusals are the
    // runner's — and must NOT come from a diagnostic.
    const srcs = [_][:0]const u8{
        "(read)\nsong.mid",
        "; a harness that asks nothing at all\n",
    };
    for (srcs) |src| {
        const probe = try testParse(arena, src);
        try t_.expect(probe.directives == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) == null);
    }
}

test "corpus harness: every declared directive is one this half implements" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // `plan` and `export-score` reach the edit engine and the exporter.
    const d = (try testParse(arena,
        \\(read)
        \\(plan transpose :args (a :semitones 12))
        \\(export-score)
    )).directives.?;
    try t_.expectEqual(@as(usize, 3), d.len);
    try t_.expectEqual(Directive.read, d[0]);
    try t_.expectEqualStrings("{\"op\":\"transpose\",\"semitones\":12}", d[1].plan);
    try t_.expectEqual(@as(u32, 12), d[2].export_score.lines);
    try t_.expectEqual(@as(u32, 512), d[2].export_score.max_keys);

    // …and `timing` is no longer a directive at all. It was the one head
    // the manifest declared and nothing implemented — the studio's
    // timing provider, and pstudio is not a host — so a case that asked
    // for it validated and then FAILED as `UNRUN timing`. The manifest
    // was the only thing keeping it alive, so removing it from there is
    // the whole change: the head is now an SJON `unknown_form`, refused
    // with a span before the dispatch is reached.
    const probe = try testParse(arena, "(read)\n(timing)\n");
    try t_.expect(probe.directives == null);
    try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) != null);
}

test "corpus harness: an operation's :args cross into the engine's JSON unchanged" {
    // The one translation in this file, and the whole of it: SJON is the
    // harness's language and JSON is the engine's, so the keys, the
    // numbers, the symbols, the vectors and the nested forms cross and
    // nothing is interpreted on the way.
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const d = (try testParse(arena,
        \\(plan retime :args (a :sel (s :lanes [flash glow] :kinds [note] :range [0 46126080]) :delta -120 :allow-shared true))
        \\(plan rename :args (a :what lane :from "old name" :to roll))
        \\(plan merge)
    )).directives.?;
    try t_.expectEqualStrings(
        "{\"op\":\"retime\",\"sel\":{\"lanes\":[\"flash\",\"glow\"],\"kinds\":[\"note\"]," ++
            "\"range\":[0,46126080]},\"delta\":-120,\"allow-shared\":true}",
        d[0].plan,
    );
    try t_.expectEqualStrings(
        "{\"op\":\"rename\",\"what\":\"lane\",\"from\":\"old name\",\"to\":\"roll\"}",
        d[1].plan,
    );
    // An operation with no arguments at all is still an operation.
    try t_.expectEqualStrings("{\"op\":\"merge\"}", d[2].plan);
}

test "corpus verdict: byte-equal is silence, and a difference names the first line" {
    try t_.expectEqual(@as(?Mismatch, null), firstDifference("(arena)\n(b)\n", "(arena)\n(b)\n"));

    const diff = firstDifference("(arena)\n(b)\n", "(arena)\n(c)\n").?;
    try t_.expectEqual(@as(usize, 2), diff.line);
    try t_.expectEqualStrings("(b)", diff.expected.?);
    try t_.expectEqualStrings("(c)", diff.actual.?);

    // A golden that ends early, and one that runs on: the side that ran
    // out is `null`, which the report spells `<end of file>`.
    const short = firstDifference("(arena)\n", "(arena)\n(b)\n").?;
    try t_.expectEqual(@as(usize, 2), short.line);
    try t_.expectEqualStrings("", short.expected.?);
    try t_.expectEqualStrings("(b)", short.actual.?);

    // A missing final newline — the one difference that is not visible
    // in any line's text. It shows up as the line PAST the shorter
    // text's last: nothing on one side, an empty line on the other, and
    // the report spells the nothing `<end of file>`.
    const trailing = firstDifference("(arena)", "(arena)\n").?;
    try t_.expectEqual(@as(usize, 2), trailing.line);
    try t_.expectEqual(@as(?[]const u8, null), trailing.expected);
    try t_.expectEqualStrings("", trailing.actual.?);
}

/// A case rendered the way `runCase` renders it, into the test's arena.
/// The report writer is a sink: these cases have no defect to report.
///
/// The environment is the run's, minus a corpus on disk: a test's fixture
/// is bytes a `Builder` wrote, so `root` and `name` name a directory that
/// is never opened unless a directive asks for an anchor — which none of
/// these do.
fn testRender(arena: Allocator, fixture: Fixture, directives: []const Directive) ![]const u8 {
    var schema = try Schema.load(t_.allocator);
    defer schema.deinit();
    var report: Io.Writer.Allocating = .init(arena);
    var aw: Io.Writer.Allocating = .init(arena);
    const rep: Report = .{ .out = &report.writer, .name = "test" };
    const env: Env = .{ .io = t_.io, .schema = &schema, .root = "corpus", .name = "test" };
    try t_.expect(try renderCase(t_.allocator, arena, env, &aw.writer, fixture, directives, rep));
    try t_.expectEqualStrings("", report.written());
    return aw.written();
}

/// The lowercase hex digest, as the golden spells it — the test's own
/// hand on the same bytes, so an expectation below says WHICH buffer the
/// renderer was supposed to hash.
fn testDigest(arena: Allocator, bytes: []const u8) ![]const u8 {
    var out: Io.Writer.Allocating = .init(arena);
    try writeDigest(&out.writer, bytes);
    return out.written();
}

test "corpus render: an SMF case — the fixture line, the read echo, both rungs and the writer" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const gpa = t_.allocator;

    // One canonical file: the writer's own output, so rung 1 holds.
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 96 };
    const track = try b.addTrack();
    try b.addEvent(track, 0, .set_tempo, .{ .tempo = 500_000 });
    try b.addEvent(track, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(track, 96, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    var seq = try b.finish();
    defer seq.deinit();
    var file = try smf.write(gpa, &seq, .{});
    defer file.deinit();

    // …and the same bytes through the format-0 merge, which is what the
    // `(write …)` line has to be describing.
    var back = try smf.read(gpa, file.bytes);
    defer back.deinit();
    var merged = try smf.write(gpa, &back.sequence, .{ .format0 = true });
    defer merged.deinit();

    const text = try testRender(
        arena,
        .{ .file = "song.mid", .bytes = try arena.dupeZ(u8, file.bytes), .kind = .smf },
        &.{
            .read,
            .roundtrip,
            .{ .write = .{ .format0 = true } },
        },
    );

    const want = try std.fmt.allocPrint(arena,
        \\; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
        \\(fixture :file "song.mid" :bytes {d} :sha256 "{s}")
        \\(read
        \\  (smf :format 0 :division 96 :smpte none :tracks 1 :events 4 :running-status 0 :foreign 0))
        \\(roundtrip
        \\  (rung1 :ok true :sha256 "{s}")
        \\  (rung2 :ok true))
        \\(write :format0 true :sha256 "{s}" :bytes {d} :tracks 1 :events 4)
        \\
    , .{
        file.bytes.len,
        try testDigest(arena, file.bytes),
        try testDigest(arena, file.bytes),
        try testDigest(arena, merged.bytes),
        merged.bytes.len,
    });
    try t_.expectEqualStrings(want, text);
}

test "corpus render: an IT case — the read echo and the walk's row map" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const gpa = t_.allocator;

    // `walk-constant`'s module: four rows of six ticks, one note.
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("render");
    try b.addOrder(0);
    const pat = try b.addPattern(4);
    pat.at(0, 0).* = .{ .note = 60 };
    var m = b.finish();
    defer m.deinit();
    // `:loose` because a four-row pattern is under IT 2.14's floor of
    // 32: the corners are about rows, and the reader honours them.
    var file = try itf.write.write(gpa, &m, null, .{ .loose = true });
    defer file.deinit();

    const text = try testRender(
        arena,
        .{ .file = "song.it", .bytes = try arena.dupeZ(u8, file.bytes), .kind = .it },
        &.{
            .read,
            .{ .walk = 1 << 20 },
        },
    );

    var read_back = try itf.read.read(gpa, file.bytes);
    defer read_back.deinit();
    const rows_diag = read_back.diags.items()[0];

    const want = try std.fmt.allocPrint(arena,
        \\; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
        \\(fixture :file "song.it" :bytes {d} :sha256 "{s}")
        \\(read
        \\  (it :title "render" :speed 6 :tempo 125 :orders 2 :patterns 1 :instruments 0 :samples 0 :message-len 0 :tmpu false)
        \\  (diag :code {d} :severity warning :start {d} :end {d} :message "pattern 0 has 4 rows, outside IT's strict 32–200"))
        \\(walk :max-rows 1048576
        \\  (row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 1 :start 6 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 2 :start 12 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 3 :start 18 :ticks 6)
        \\  (segment :tick 0 :tempo 125)
        \\  (onset :ch 0 :tick 0 :note 60)
        \\  (total :ticks 24 :loop-row 0))
        \\
    , .{
        file.bytes.len,
        try testDigest(arena, file.bytes),
        @intFromEnum(Diag.Code.it_pattern_rows_out_of_range),
        rows_diag.span.start,
        rows_diag.span.end,
    });
    try t_.expectEqualStrings(want, text);
}

test "corpus render: diagnostics carry the ordinal, the span and an escaped message" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var diags: Diag.List = .init(t_.allocator);
    defer diags.deinit();
    try diags.add(.walk_runaway, .err, .{ .start = 1, .end = 2 }, "gave up", .{});
    try diags.add(
        .it_command_unknown,
        .warning,
        .{ .start = 3, .end = 5 },
        "a \"quoted\" \\ word",
        .{},
    );
    try diags.add(
        .smpte_tempo_ignored,
        .info,
        .{ .start = 0, .end = 0 },
        "kept, not believed",
        .{},
    );

    var aw: Io.Writer.Allocating = .init(arena);
    try t_.expect(try renderDiags(&aw.writer, "  ", &diags, .{ .out = null, .name = "test" }));

    // The CODE is the numeric ordinal, not the name: the ordinal is the
    // wire, and `zig build audit-diagnostics` is what keeps every name
    // in a test. A quote and a backslash are escaped; nothing else is.
    const want = try std.fmt.allocPrint(arena,
        \\
        \\  (diag :code {d} :severity error :start 1 :end 2 :message "gave up")
        \\  (diag :code {d} :severity warning :start 3 :end 5 :message "a \"quoted\" \\ word")
        \\  (diag :code {d} :severity info :start 0 :end 0 :message "kept, not believed")
    , .{
        @intFromEnum(Diag.Code.walk_runaway),
        @intFromEnum(Diag.Code.it_command_unknown),
        @intFromEnum(Diag.Code.smpte_tempo_ignored),
    });
    try t_.expectEqualStrings(want, aw.written());
}

test "corpus render: a walk longer than the echo cap says how much it left out" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const gpa = t_.allocator;

    // 22 orders of one 200-row pattern, a note on every row: 4400 rows
    // played and 4400 onsets, 304 of each past the 4096 the echo
    // carries. A golden nobody can read is not evidence.
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    for (0..22) |_| try b.addOrder(0);
    const pat = try b.addPattern(200);
    for (0..200) |row| pat.at(row, 0).* = .{ .note = 60 };
    var m = b.finish();
    defer m.deinit();

    var aw: Io.Writer.Allocating = .init(arena);
    try t_.expect(try renderWalk(gpa, &aw.writer, &m, 1 << 20, .{ .out = null, .name = "test" }));
    const text = aw.written();

    try t_.expect(
        std.mem.indexOf(u8, text, "(row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)") != null,
    );
    try t_.expect(std.mem.indexOf(u8, text, "(rows-elided 304)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(onsets-elided 304)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(total :ticks 26400 :loop-row 0)") != null);
    // 4096 of each echoed and not one more.
    try t_.expectEqual(@as(usize, 4096), std.mem.count(u8, text, "\n  (row :"));
    try t_.expectEqual(@as(usize, 4096), std.mem.count(u8, text, "\n  (onset :"));
}

