test "corpus harness: a bit pattern's WIDTH is the runner's, not the schema's" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // 16 hex digits for an f64 — a string carries no width, so the
    // manifest cannot state it and the runner does. Not a diagnostic.
    for ([_][:0]const u8{
        "(times \"3FE\")",
        "(times \"3FE0000000000000F\")",
        "(times \"3FE000000000000G\")",
        "(snap :tick 0 :grid q16 :swing \"1\")",
    }) |src| {
        const probe = try testParse(arena, src);
        try t_.expect(probe.directives == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, "16 hex digits") != null);
    }
}

/// The `(echo …)` form of a golden: from its opening line to the line
/// that closes it. Null when the golden carries none, which is how a
/// case that loads no document is told from one whose header moved.
fn echoBlock(golden: []const u8) ?[]const u8 {
    const start = std.mem.indexOf(u8, golden, "\n(echo\n") orelse return null;
    // The form closes on the first line at column 0 after it — every
    // child is indented by two.
    var at = start + 1;
    while (std.mem.indexOfScalarPos(u8, golden, at, '\n')) |nl| {
        if (nl + 1 >= golden.len or golden[nl + 1] != ' ') return golden[start + 1 .. nl + 1];
        at = nl + 1;
    }
    return golden[start + 1 ..];
}

/// One corpus case's file, read from the repo rather than from wherever
/// `zig build test` was invoked. `build_options` is the test module's;
/// the executable never reaches this.
fn readCorpusFile(gpa: Allocator, case: []const u8, file: []const u8) ![]u8 {
    const repo_root = @import("build_options").repo_root;
    const path = try std.fs.path.join(gpa, &.{ repo_root, "corpus", case, file });
    defer gpa.free(path);
    return Io.Dir.cwd().readFileAlloc(t_.io, path, gpa, .limited(MAX_FILE_BYTES));
}

/// Every spelling of plan 03's three-segment map: the document's own
/// points, an inline SMF dump, an inline IT module — and the same SMF
/// file named BY REFERENCE, which is the spelling the final review's C1
/// found being timed by the placeholder instead.
const three_conductors = [_][]const u8{
    "tempo-three-conductors-native",
    "tempo-three-conductors-smf",
    "tempo-three-conductors-it",
    "tempo-by-reference-conductor",
};

test "corpus: every spelling of one conductor has the same echo header" {
    // Plan 03, phase 3's red: the same three-segment map authored
    // natively, as an SMF with tempo on TRACK 2, as an IT module with
    // `Txx` rows, and as a by-reference anchor produces byte-identical
    // `TimeMap` text.
    //
    // Asserted over the committed GOLDENS, which is the strongest place
    // to put it: `zig build corpus` already pins each golden against what
    // the runner renders today, so three goldens that agree mean three
    // derivations that agree — and a hand-edited golden fails here as
    // well as there.
    const gpa = t_.allocator;

    var first: ?[]const u8 = null;
    var first_owned: []u8 = &.{};
    defer gpa.free(first_owned);
    for (three_conductors) |case| {
        const golden = try readCorpusFile(gpa, case, "expected.sjon");
        // The first case's text is KEPT — `first` points into it — and
        // every other one is freed on the way out, failure included. One
        // flag rather than a `defer` and an `errdefer`, which would both
        // fire on a failed comparison.
        var keep = false;
        defer if (!keep) gpa.free(golden);

        const echo = echoBlock(golden) orelse {
            std.debug.print("corpus case {s} has no (echo …) header\n", .{case});
            return error.NoEchoHeader;
        };
        if (first) |want| {
            t_.expectEqualStrings(want, echo) catch |err| {
                std.debug.print("the echo header of {s} is not the native one's\n", .{case});
                return err;
            };
        } else {
            keep = true;
            first_owned = golden;
            first = echo;
        }
    }
    // Three segments, three meters-free lines and a length: if the
    // header ever became empty the loop above would compare nothing.
    try t_.expect(std.mem.count(u8, first.?, "(segment :tick ") == 3);
}

test "corpus: fromSjon's conductor map and derive's agree on the three conductors" {
    // Two independent paths build a `TimeMap` from one document —
    // `doc/fromSjon.zig` while it is lowering the source, and
    // `time/derive.zig` over the finished value — and a host may read
    // either. They are the same tables or they are a bug; the three
    // conductors are where that is worth pinning, because each takes a
    // different arm of both.
    //
    // Each is asked twice: as committed, and with `:length 1bar` struck
    // out. The second is the one that matters — with no authored length
    // the two layers have to agree on plan 02's DEFAULT ("the end of the
    // last event or clip, rounded up to a bar") over material that is the
    // conductor's rather than the document's, which is the one place they
    // genuinely differed before 1c9cecf.
    const gpa = t_.allocator;

    var schema = try Schema.load(gpa);
    defer schema.deinit();

    const strip: ?SourceEdit = .{ .from = " :length 1bar", .to = "" };

    for (three_conductors) |case| {
        for ([_]?SourceEdit{ null, strip }) |edit| {
            var loaded = try loadCaseDoc(gpa, &schema, case, edit);
            defer loaded.deinit();
            try t_.expect(!loaded.loadDiags().hasErrors());

            var from_source: Io.Writer.Allocating = .init(gpa);
            defer from_source.deinit();
            var from_derive: Io.Writer.Allocating = .init(gpa);
            defer from_derive.deinit();
            try loaded.map().echo(&from_source.writer);
            try loaded.derived.map.echo(&from_derive.writer);

            t_.expectEqualStrings(from_source.written(), from_derive.written()) catch |err| {
                std.debug.print("{s}{s}: the two conductor paths disagree\n", .{
                    case,
                    if (edit == null) "" else " (no :length)",
                });
                return err;
            };
            // The stripped document really did lose its length — a
            // silent no-op edit would make the second half of this loop
            // the first half again — and BOTH layers then computed the
            // default rather than reading one.
            //
            // What that default comes out as is `fromSjon.contentEnd`'s
            // business and not this test's: these three documents place
            // no note and no clip, so the answer is 0 whichever
            // conductor keeps time, and the claim here is only that the
            // two layers say the same thing about it.
            if (edit != null) {
                try t_.expect(loaded.doc_().length == null);
                try t_.expectEqual(loaded.map().length, loaded.derived.map.length);
            }
        }
    }
}

/// A three-line document, in memory: 120 quarter notes per minute in
/// [4 4], one bar long, with a section and a cue so the two position
/// queries have something to answer with.
const test_doc: [:0]const u8 =
    \\(timeline :title "render" :length 1bar)
    \\(tempo-point :at 0q :us 500000)
    \\(meter-point :at 0bar :sig [4 4])
    \\(section :name whole :at 0bar :dur 1bar)
    \\(cue :name "two" :at 2q)
    \\
;

fn testDocFixture() Fixture {
    return .{ .file = "doc.sjon", .bytes = test_doc, .kind = .doc };
}

test "corpus render: a document case — the echo header, both queries and a snap" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Hand computation. 500 000 microseconds to the quarter is two ticks
    // of the clock per bar: 1 s is two quarters, which is tick
    // 92 252 160 and beat 2 — and the cue sits exactly there, so it is
    // the PREVIOUS one (`c.at <= tick`) and there is none ahead.
    // A `q16` line is TPQ / 4 = 11 531 520 ticks; tick 100 000 000 sits
    // between lines 8 and 9 of the bar, nearer 9. Bar 0 starts at tick 0,
    // so `:into-bar` is the whole second the query asked about.
    const text = try testRender(arena, testDocFixture(), &.{
        .{ .times = &.{1.0} },
        .{ .at = 92_252_160 },
        .{ .snap = .{ .tick = 100_000_000, .grid = .q16, .swing = 0 } },
    });

    try t_.expectEqualStrings(
        \\; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
        \\(fixture :file "doc.sjon" :bytes 172 :sha256 "6b611f07af795e82628856420432c6a9c800fb12396fe92d78197f8c25f4cad4")
        \\(echo
        \\  (segment :tick 0 :us 500000 :tps "4195FEA000000000" :start-sec "0000000000000000")
        \\  (meter :tick 0 :sig [4 4] :first-bar 0)
        \\  (bars :count 2 :last-start 184504320)
        \\  (length :tick 184504320 :end hold :loop-secs "4000000000000000")
        \\  (section :name whole :at 0 :dur 184504320)
        \\  (cue :name "two" :at 92252160))
        \\(at :seconds "3FF0000000000000" :tick 92252160 :bar 0 :beat 2 :sub 0 :into-bar "3FF0000000000000" :sections [0] :prev-cue 0 :next-cue none)
        \\(at :tick 92252160 :bar 0 :beat 2 :sub 0 :into-bar "3FF0000000000000" :sections [0] :prev-cue 0 :next-cue none)
        \\(snapped :tick 103783680)
        \\
    , text);
}

test "corpus render: a seconds query that no clock can answer is refused by NAME" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // `at` takes seconds from OUTSIDE, so the two host guards ride out
    // with it. A golden spells the refusal the way it spells every other
    // symbol — kebab-case — because the golden is not Zig and a reader
    // comparing it to `Diag.Code`'s names should not have to translate.
    //
    // A LOOPING document, because that is where a non-finite second
    // survives long enough to be refused: `hold` clamps with `@min`,
    // which is IEEE `minNum` and answers the finite side, so a NaN
    // handed to a held document quietly becomes its end. `loop` takes
    // `@mod`, and a NaN stays one.
    const source: [:0]const u8 =
        \\(timeline :title "refused" :length 1bar :end loop)
        \\(tempo-point :at 0q :us 500000)
        \\(meter-point :at 0bar :sig [4 4])
        \\
    ;
    const text = try testRender(arena, .{ .file = "doc.sjon", .bytes = source, .kind = .doc }, &.{
        .{ .times = &.{ std.math.nan(f64), std.math.inf(f64) } },
    });
    try t_.expect(
        std.mem.indexOf(
            u8,
            text,
            "(at :seconds \"7FF8000000000000\" :refused non-finite-time)",
        ) != null,
    );
    try t_.expect(
        std.mem.indexOf(
            u8,
            text,
            "(at :seconds \"7FF0000000000000\" :refused non-finite-time)",
        ) != null,
    );
}

/// Load one of the corpus's own `doc.sjon` files and derive it — the
/// join the tests below need, over documents a reviewer can open.
const LoadedCase = struct {
    /// The case's own directory, as a resolver — the same store
    /// `loadDocument` builds for the real walk, because an anchor's
    /// `:file` is resolved relative to the document (plan 02) and a
    /// conducted anchor's bytes ARE its time (plan 03). It outlives the
    /// document: an inline IT tier's opaque regions are offsets into the
    /// bytes it cached.
    store: FsStore,
    result: doc.Result,
    derived: time.derive.Derived,

    fn deinit(self: *LoadedCase) void {
        self.derived.deinit();
        self.result.deinit();
        self.store.deinit();
    }

    // The three questions `Loaded` answers, spelled the same way, so a
    // test reads the same whichever of the two it holds.
    fn doc_(self: *LoadedCase) *doc.Doc {
        return &self.result.doc;
    }

    fn loadDiags(self: *const LoadedCase) *const Diag.List {
        return &self.result.diags;
    }

    fn map(self: *const LoadedCase) *const time.TimeMap.TimeMap {
        return &self.result.map;
    }
};

/// One literal substitution over a case's source, so a test can ask the
/// same document with and without a line.
const SourceEdit = struct { from: []const u8, to: []const u8 };

fn loadCaseDoc(
    gpa: Allocator,
    schema: *const Schema,
    case: []const u8,
    edit: ?SourceEdit,
) !LoadedCase {
    const raw = try readCorpusFile(gpa, case, "doc.sjon");
    defer gpa.free(raw);

    const text: []const u8 = if (edit) |e| blk: {
        const at = std.mem.indexOf(u8, raw, e.from) orelse return error.CaseTextNotFound;
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(gpa);
        try out.appendSlice(gpa, raw[0..at]);
        try out.appendSlice(gpa, e.to);
        try out.appendSlice(gpa, raw[at + e.from.len ..]);
        break :blk try gpa.dupe(u8, out.items);
    } else raw;
    defer if (edit != null) gpa.free(text);

    const source = try gpa.dupeZ(u8, text);
    defer gpa.free(source);

    const case_dir = try std.fs.path.join(gpa, &.{
        @import("build_options").repo_root,
        "corpus",
        case,
    });
    defer gpa.free(case_dir);
    var store: FsStore = .init(gpa, t_.io, case_dir);
    errdefer store.deinit();

    var result = try doc.fromSource(gpa, schema, source, store.resolver());
    errdefer result.deinit();
    const derived = try time.derive.derive(gpa, &result.doc);
    return .{ .store = store, .result = result, .derived = derived };
}

/// Every field of a `Position`, one against the other. `seconds_into_bar`
/// is compared by BIT PATTERN, because an ulp is exactly the difference
/// the two paths could have.
fn expectSamePosition(want: Playhead.Position, got: Playhead.Position) !void {
    try t_.expectEqual(want.tick, got.tick);
    try t_.expectEqual(want.bar, got.bar);
    try t_.expectEqual(want.beat, got.beat);
    try t_.expectEqual(want.sub_ticks, got.sub_ticks);
    try t_.expectEqual(
        @as(u64, @bitCast(want.seconds_into_bar)),
        @as(u64, @bitCast(got.seconds_into_bar)),
    );
    try t_.expectEqualSlices(u32, want.section_ids, got.section_ids);
    try t_.expectEqual(want.prev_cue, got.prev_cue);
    try t_.expectEqual(want.next_cue, got.next_cue);
    try t_.expectEqual(want.order_row, got.order_row);
}

test "corpus: the two position queries agree wherever the seconds seam is exact" {
    // `(at :tick N)` answers with `Playhead.atTick` and `(times …)` with
    // `Playhead.at`; the second is the first plus the wrap and the
    // seconds→tick conversion. The claim this pins is plan 03's: a
    // SEGMENT START is exact in both directions, so the two queries give
    // the same answer there, field for field — and everywhere else the
    // grid answer for whatever tick the clock landed on is the same
    // answer the clock got, which is what makes the two renderer arms
    // one query asked two ways.
    //
    // Over the corpus's own documents rather than a toy: four tempo
    // segments in `seams-three-segment` and a [3 4] → [4 4] change in
    // `meter-change`, so `bar`, `beat` and `sub` are non-zero and the
    // meter in force is not the same one everywhere.
    const gpa = t_.allocator;
    var schema = try Schema.load(gpa);
    defer schema.deinit();

    const cases = [_]struct { name: []const u8, interior: []const i64 }{
        .{
            .name = "seams-three-segment",
            // A tick inside each of the four segments, none of them on a
            // beat line: `sub` is non-zero at every one.
            .interior = &.{ 12_345_678, 60_000_000, 100_000_000, 150_000_000 },
        },
        .{
            .name = "meter-change",
            // Mid-bar on both sides of the meter change, and one tick
            // past the bar table's end where the last meter carries on.
            .interior = &.{ 70_000_000, 207_567_360, 322_882_560, 900_000_000 },
        },
        .{
            .name = "playhead-sections-cues",
            .interior = &.{ 1, 100_000_000, 300_000_000, 500_000_000 },
        },
        .{
            .name = "tempo-three-conductors-it",
            .interior = &.{ 10_000_000, 70_000_000, 120_000_000 },
        },
    };

    for (cases) |c| {
        var loaded = try loadCaseDoc(gpa, &schema, c.name, null);
        defer loaded.deinit();
        try t_.expect(!loaded.loadDiags().hasErrors());
        // A document worth asking: more than one segment, or a meter that
        // changes. A fixture that quietly became trivial would make every
        // comparison below vacuous.
        try t_.expect(loaded.derived.map.segments.len > 1 or loaded.derived.map.meters.len > 1);

        // Segment starts: exact both ways, so every field matches.
        for (loaded.derived.map.segments) |seg| {
            var by_tick = try Playhead.atTick(gpa, &loaded.derived, seg.tick);
            defer by_tick.deinit(gpa);
            var by_seconds = try Playhead.at(
                gpa,
                &loaded.derived,
                Playhead.secondsOf(&loaded.derived, seg.tick),
            );
            defer by_seconds.deinit(gpa);
            expectSamePosition(by_seconds, by_tick) catch |err| {
                std.debug.print(
                    "{s}: the two queries disagree at segment start {d}\n",
                    .{ c.name, seg.tick },
                );
                return err;
            };
        }

        // Interior ticks: ask the clock, then ask the grid about the tick
        // the clock landed on. The two are the same answer or the copy
        // has drifted.
        for (c.interior) |tick| {
            var by_seconds = try Playhead.at(
                gpa,
                &loaded.derived,
                Playhead.secondsOf(&loaded.derived, tick),
            );
            defer by_seconds.deinit(gpa);
            var by_tick = try Playhead.atTick(gpa, &loaded.derived, by_seconds.tick);
            defer by_tick.deinit(gpa);
            // The one field the clock answers better than the grid: it is
            // measured from the second that was ASKED about, which at an
            // interior tick may sit an ulp above the tick's own second.
            by_tick.seconds_into_bar = by_seconds.seconds_into_bar;
            expectSamePosition(by_seconds, by_tick) catch |err| {
                std.debug.print("{s}: the two queries disagree at tick {d}\n", .{ c.name, tick });
                return err;
            };
            // …and a non-trivial position, so the comparison has
            // something to compare.
            try t_.expect(by_tick.bar > 0 or by_tick.beat > 0 or by_tick.sub_ticks > 0);
        }
    }
}

test "corpus render: a native document is RENDERED into both kinds, with rung 1 and rung 3" {
    // The half plan 08 phase 5 added: a document with no tier is not
    // unanswerable any more, it is rendered — and the golden carries the
    // bytes, what the residue cost, and both rungs.
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const text = try testRender(arena, testDocFixture(), &.{
        .{ .build = .{ .kind = .mid, .cc = 74 } },
        .{ .build = .{ .kind = .it, .cc = null } },
    });
    try t_.expect(std.mem.indexOf(u8, text, "(built :kind mid :len") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(built :kind it :len") != null);
    try t_.expect(std.mem.indexOf(u8, text, ":unsupported") == null);
    // Rung 3 is the gate this task exists for: what was built dumps back
    // as the document that built it.
    try t_.expect(std.mem.indexOf(u8, text, "(rung1 :ok true)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(rung3 :ok true)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(residue :essence ") != null);
}

test "corpus render: the snap grids the manifest offers are exactly the ones the playhead names" {
    // `parseHarness` converts a `:grid` symbol with `.?`, which is sound
    // only while the manifest's member set and `Playhead.SnapGrid` are
    // the same list. Both directions, so neither can grow alone.
    inline for (@typeInfo(Playhead.SnapGrid).@"enum".fields) |f| {
        const needle = "(member :name " ++ f.name ++ " ";
        try t_.expect(std.mem.indexOf(u8, Schema.corpus_manifest_src, needle) != null);
    }
    const kinds = Schema.corpus_manifest_src[std.mem.indexOf(
        u8,
        Schema.corpus_manifest_src,
        "(value-kind :name snap-grid",
    ).?..];
    const set = kinds[0..std.mem.indexOf(u8, kinds, "(value-kind :name row-cap").?];
    try t_.expectEqual(
        @typeInfo(Playhead.SnapGrid).@"enum".fields.len,
        std.mem.count(u8, set, "(member :name "),
    );
}

/// A case the renderer REFUSES, with what it said about it. The mirror
/// of `testRender`, for the defects that void a golden.
fn testRenderRefused(
    arena: Allocator,
    fixture: Fixture,
    directives: []const Directive,
) ![]const u8 {
    var schema = try Schema.load(t_.allocator);
    defer schema.deinit();
    var report: Io.Writer.Allocating = .init(arena);
    var aw: Io.Writer.Allocating = .init(arena);
    const rep: Report = .{ .out = &report.writer, .name = "test" };
    const env: Env = .{ .io = t_.io, .schema = &schema, .root = "corpus", .name = "test" };
    try t_.expect(!try renderCase(t_.allocator, arena, env, &aw.writer, fixture, directives, rep));
    return report.written();
}

test "corpus render: a directive nothing implements is UNRUN, whatever the fixture is" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const gpa = t_.allocator;

    // A document case: no document directive precedes the unrun one, so
    // nothing was loaded — and the refusal has to say so without
    // reaching for a document that is not there.
    const on_doc = try testRenderRefused(arena, testDocFixture(), &.{.{ .unrun = "plan" }});
    try t_.expect(std.mem.indexOf(u8, on_doc, "UNRUN plan") != null);

    // …and a byte case, where the same arm sits beside the ones that do
    // reach for one.
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 96 };
    const track = try b.addTrack();
    try b.addEvent(track, 0, .set_tempo, .{ .tempo = 500_000 });
    var seq = try b.finish();
    defer seq.deinit();
    var file = try smf.write(gpa, &seq, .{});
    defer file.deinit();

    const on_bytes = try testRenderRefused(
        arena,
        .{ .file = "song.mid", .bytes = try arena.dupeZ(u8, file.bytes), .kind = .smf },
        &.{ .read, .{ .unrun = "export-score" } },
    );
    try t_.expect(std.mem.indexOf(u8, on_bytes, "UNRUN export-score") != null);
}

test "corpus render: a byte directive on a document case names what it needed" {
    var arena_state = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // `doc.sjon` is source, not a file either core would recognise, so
    // `(read)` and `(walk …)` have nothing to read.
    for ([_]Directive{ .read, .roundtrip, .{
        .walk = 16,
    }, .{ .write = .{ .format0 = false } } }) |d| {
        const said = try testRenderRefused(arena, testDocFixture(), &.{ .dump, d });
        try t_.expect(std.mem.indexOf(u8, said, "needs a song.mid or song.it fixture") != null);
    }
}
